INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3465', 'spa', 'yashan -- viejo, añejo; describe cosas almacenadas con el tiempo o de larga data', 'Homónimo del más frecuente yashen (''dormido''), este adjetivo yashan significa ''viejo'' en el sentido de añejo, almacenado o de larga data. Sus siete apariciones se agrupan en dos campos: productos agrícolas almacenados — la ''cosecha añeja'' que Israel comerá gracias a la bendición de Dios (Lv 25:22; 26:10) y los frutos ''viejos y nuevos'' de Cantares 7:14 — y estructuras antiguas, notablemente la ''Puerta Vieja'' en la Jerusalén de Nehemías (Neh 3:6; 12:39) y el ''estanque viejo'' de Isaías (Is 22:11). La conexión etimológica con el sueño es sugerente: lo ''viejo'' ha permanecido, por así decirlo, en reposo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3467', 'spa', 'Salvar, librar, rescatar (Hifil); salvador o libertador (participio Hifil); ser salvado o recibir salvación (Nifal)', 'יָשַׁע es la raíz verbal que subyace a algunos de los nombres y conceptos más importantes de la Escritura: Josué, Jesús (Yeshúa), Isaías (Yesha''yahu) y el sustantivo yeshu''ah («salvación»). En su forma Hifil dominante significa librar o rescatar del peligro, de los enemigos o de la opresión, con Dios o un campeón humano como sujeto. El participio Hifil moshia'' («salvador», «libertador») se convierte en un cuasi-título para Dios en los profetas y para los jueces que rescatan a Israel. El Nifal pasivo captura la otra cara del mismo evento: «ser salvado», «experimentar la liberación». La amplitud de la raíz — desde la liberación en el campo de batalla hasta la salvación escatológica — la convierte en uno de los verbos teológicamente más trascendentales de la Biblia hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3468', 'spa', 'Liberación, salvación, seguridad — el acto rescatador de Dios o el estado resultante de protección y bienestar.', 'Liberación, salvación, seguridad — el acto rescatador de Dios o el estado resultante de protección y bienestar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3469', 'spa', 'Yisi — nombre propio masculino que significa ''salutífero'' o ''salvador'', llevado por cuatro hombres en Crónicas', 'Yisi (que significa ''él salva'' o ''salutífero'') es un nombre propio hebreo compartido por cuatro individuos en las genealogías del Cronista. Entre ellos figuran un descendiente de Jerameel (1 Cr 2:31), un jefe de Judá (1 Cr 4:20), un líder de Simeón que encabezó una expedición contra los amalecitas en el monte Seir (1 Cr 4:42) y un jefe de la media tribu de Manasés (1 Cr 5:24). La raíz del nombre en la salvación (ישע) refleja una esperanza teofórica característica de las prácticas onomásticas israelitas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3470a', 'spa', 'Isaías (Yeshayahu) — ''Yah es salvación'', el profeta hijo de Amoz que ministró en el Judá del siglo VIII a.C.', 'Isaías (Yeshayahu) — ''Yah es salvación'', el profeta hijo de Amoz que ministró en el Judá del siglo VIII a.C.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3470b', 'spa', 'Jesaías, nombre de cuatro israelitas postexílicos (distinto del profeta Isaías)', 'Jesaías, cuyo significado es «salvación de Yahvé», aparece como nombre de cuatro individuos distintos del período postexílico, diferenciados del gran profeta Isaías. Entre ellos figuran un descendiente de Zorobabel, un jefe que regresó con Esdras, un líder levítico y un benjaminita. El elemento teofórico del nombre (Yah) indica que estos individuos portaban testimonio de la obra salvífica de Yahvé, un patrón común en la onomástica hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3471', 'spa', 'jaspe, piedra preciosa (préstamo del persa, posiblemente similar al jade)', 'Piedra preciosa mencionada en las listas del pectoral del sumo sacerdote, identificada como préstamo del persa relacionado con el jade. Aparece en Éxodo 28:20 y 39:13 (fuente sacerdotal) como la tercera piedra de la cuarta fila del pectoral, junto al berilo y el ónice, y en Ezequiel 28:13 entre las piedras que adornan al rey de Tiro en su esplendor edénico. El término es un préstamo del persa (یَشْم), adoptado también en árabe (يَشْبٌ) y posiblemente reflejado en el acadio ašpû. Las traducciones antiguas varían en su identificación, pero ''jaspe'' se ha consolidado como término estándar, refiriéndose a un cuarzo opaco apreciado por sus colores y pulido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3474', 'spa', 'Ser recto, correcto o agradable; en Piel/Hifil, enderezar, dirigir o allanar; físicamente, ir directamente hacia adelante', 'Ser recto, correcto o agradable; en Piel/Hifil, enderezar, dirigir o allanar; físicamente, ir directamente hacia adelante');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3476', 'spa', 'Rectitud, integridad moral; la cualidad de caminar en línea recta ante Dios y los demás', 'Derivado de la raíz yashar (''ser recto''), yosher nombra la cualidad de vivir en alineación moral — caminos rectos, palabras rectas, un corazón recto. Proverbios lo presenta como principio rector: los íntegros caminan en rectitud (Pr 2:13; 4:11), mientras quienes la abandonan se desvían por sendas torcidas. Salomón pide a Dios que lo evalúe según ''la rectitud de mi corazón'' (1 R 9:4), y David alaba a Dios que ''prueba el corazón y se deleita en la rectitud'' (1 Cr 29:17). Job insiste en que sus palabras brotan ''de la rectitud de mi corazón'' (Job 33:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3477', 'spa', 'Recto, íntegro, justo; de personas: moralmente recto; de acciones: correcto, agradable a Dios; físicamente: derecho, llano; también nombre propio (Libro de Yashar)', 'יָשָׁר es uno de los adjetivos morales-físicos más versátiles del hebreo, enraizado en la imagen concreta de la rectitud. Un camino puede ser yashar — llano, directo, sin tortuosidad (Sal 107:7; Jer 31:9) — y desde esa metáfora espacial la palabra se extiende poderosamente al ámbito ético. Su uso más frecuente describe personas de integridad moral: Job es tam veyashar, «íntegro y recto» (Job 1:1), y los yesharim forman una categoría social-moral reconocida en Salmos y Proverbios, opuesta a los tortuosos y los malvados. Un sentido evaluativo distinto aparece en la fórmula deuteronomista «lo recto a los ojos del SEÑOR», la vara con que se mide a cada rey de Israel y Judá. El español recto y el alemán aufrichtig preservan bellamente la metáfora de lo físico a lo moral. La palabra también aparece como nombre propio en el misterioso Libro de Yashar (Jos 10:13; 2 S 1:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3478', 'spa', 'Israel — el nombre de alianza del patriarca Jacob y la nación descendiente de él', 'Israel (יִשְׂרָאֵל) funciona tanto como nombre personal cuanto como designación nacional. Fue otorgado al patriarca Jacob tras su lucha nocturna en Peniel (Gn 32:28); el nombre se interpreta tradicionalmente como ''el que lucha con Dios'' o ''Dios persevera''. Desde ese momento designa colectivamente a los descendientes de Jacob: las doce tribus, la monarquía unida y, más tarde, específicamente el reino del norte. Con 2.507 apariciones, es el segundo nombre propio más frecuente en la Biblia hebrea después de Yahvé, y se encuentra en todos los géneros, desde la narrativa del Torá hasta el oráculo profético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3479', 'spa', 'Israel — el nombre nacional del pueblo del pacto de Dios, aquí en las porciones arameas de Esdras referido a la comunidad postexílica.', 'En las secciones arameas de Esdras, el nombre Israel (Yisra''el) designa a la comunidad judía postexílica que reconstruía su identidad bajo el dominio persa. Aparece en correspondencia oficial aramea y decretos reales: ''el Dios de Israel'' (Esd 5:1; 6:14; 7:15), ''el rey de Israel'' (5:11), ''los hijos de Israel'' (6:16) y ''el pueblo de Israel'' (7:13). Aunque es el mismo nombre dado a Jacob y llevado por la nación a lo largo de las Escrituras, su forma aramea en estos contextos administrativos muestra cómo la identidad pactual de Israel pervivió incluso en la lengua del imperio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3482', 'spa', 'Israelita (gentilicio), miembro del pueblo de Israel; mujer israelita (forma femenina)', 'Adjetivo gentilicio que significa «israelita», indicando pertenencia al pueblo de Israel. Sus tres apariciones se concentran en Levítico 24:10-11, donde describen al hijo de una mujer israelita y un hombre egipcio que blasfemó el Nombre durante una disputa en el campamento. El texto identifica cuidadosamente a este hombre como «el hijo de la israelita» (v. 10), luego como «el israelita» (masculino, v. 10) y nuevamente «la mujer israelita» (v. 11). Este énfasis en su condición mestiza podría explicar por qué el caso requirió una adjudicación especial: pertenecía solo parcialmente a la comunidad del pacto. La forma femenina הַיִּשְׂרְאֵלִית resulta especialmente notable, dado que la identidad étnico-religiosa solía transmitirse por línea paterna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3484', 'spa', 'Jesurún, nombre poético de Israel que enfatiza el carácter recto e ideal de la nación', 'Jesurún aparece como un nombre afectuoso e idealizado de Israel en la poesía bíblica, derivado de יָשָׁר («recto»). Moisés lo emplea en su bendición final para designar al pueblo del pacto bajo su mejor carácter: «el recto» o «el pueblo justo». El término aparece en contextos que celebran la elección y bendición divina de Israel, aunque el cántico de Moisés lo usa irónicamente justo antes de describir cómo «Jesurún engordó y dio coces», abandonando la misma rectitud que su nombre celebra. La mayoría de los eruditos lo interpreta como un denominativo que significa «pueblo recto» y no como un diminutivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3485', 'spa', 'Isacar — noveno hijo de Jacob y Lea; la tribu israelita y su territorio asignado.', 'Isacar — noveno hijo de Jacob y Lea; la tribu israelita y su territorio asignado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3488', 'spa', 'Verbo arameo: sentarse, habitar, estar sentado; causativo: asentar o hacer habitar', 'Este verbo arameo aparece exclusivamente en los libros de Esdras y Daniel, donde porta los significados principales de sentarse (especialmente en contexto judicial) y habitar. En Daniel 7:9-10 describe al Anciano de Días tomando asiento para el juicio, una escena de autoridad cósmica. En Esdras 4:17 se refiere a pueblos que habitan en una región, mientras que la forma causativa (Hafel) en Esdras 4:10 describe el reasentamiento forzoso de poblaciones. Es el cognado arameo del hebreo común יָשַׁב.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3489', 'spa', 'Estaca, clavija o piquete usado para asegurar tiendas, anclar estructuras o servir como herramienta de tejido', 'Estaca, clavija o piquete usado para asegurar tiendas, anclar estructuras o servir como herramienta de tejido');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3490', 'spa', 'huerfano, nino sin padre — persona privada de padre, figura paradigmatica de vulnerabilidad en la ley israelita', 'huerfano, nino sin padre — persona privada de padre, figura paradigmatica de vulnerabilidad en la ley israelita');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3492', 'spa', 'Jatir, ciudad levítica en la región montañosa de Judá, al suroeste de Hebrón', 'Jatir era una ciudad en la región montañosa de Judá, asignada a los levitas como una de sus ciudades. David envió parte del botín allí tras su victoria sobre los amalecitas, lo que sugiere que era una localidad aliada que lo había apoyado durante sus años como fugitivo. Fuentes antiguas la identifican con una aldea a unos treinta kilómetros de Eleuterópolis, posiblemente la moderna ''Attir, ubicada entre Hebrón y Beerseba, aunque la identificación no es segura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3493', 'spa', 'Excelente, sobresaliente (adjetivo atributivo); en extremo, extraordinariamente (intensificador adverbial) — arameo, en Daniel', 'El adjetivo arameo יַתִּיר (yattir), emparentado con el hebreo יוֹתֵר de la raíz que significa ''exceder'', aparece exclusivamente en el libro de Daniel para expresar cualidad superlativa o grado extremo. Como adjetivo atributivo, describe el espíritu extraordinario que distinguía a Daniel por encima de los demás administradores (Dan 6:3) y la sabiduría sobresaliente hallada en él (Dan 5:12, 14). Como intensificador adverbial, lleva las descripciones al extremo: la imagen del sueño de Nabucodonosor era ''en extremo'' brillante (Dan 2:31), el horno fue calentado ''excesivamente'' más allá de lo normal (Dan 3:22), y la cuarta bestia era ''extraordinariamente'' terrible (Dan 7:7, 19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3498', 'spa', 'Quedar, sobrar, sobrevivir; en Hifil, dejar como sobrante, preservar con vida, o hacer que abunde y exceda', 'El verbo יָתַר captura la idea de excedente y supervivencia: lo que queda después de retirar la porción principal. En su forma Nifal describe restos de ofrendas (Éx 12:10; Lv 2:3), sobrevivientes de batallas y lo que permanece tras la destrucción. El Hifil causativo añade intencionalidad: dejar algo como remanente a propósito, preservar con vida o — en una notable extensión semántica — causar abundancia y exceso (Dt 28:11; Gn 49:4). El español alterna entre quedar (permanecer) y dejar (causar que permanezca), mientras que el sentido Hifil de abundancia recurre a sobrar y hacer abundar, revelando una frontera semántica real dentro de la propia forma causativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3499a', 'spa', 'Resto, remanente o residuo de un grupo; también excelencia o preeminencia, excedente o abundancia, y adverbialmente ''en gran manera''.', 'Resto, remanente o residuo de un grupo; también excelencia o preeminencia, excedente o abundancia, y adverbialmente ''en gran manera''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3499b', 'spa', 'Cuerda o cordel — ya sea la cuerda de un arco para armas o la soga de una tienda, de una raíz que significa colgar o estirar', 'Este sustantivo yeter (II) designa una cuerda o cordel, ramificándose en dos contextos de uso en la Biblia hebrea. En el relato de Sansón (Jue 16:7-9), se refiere a cuerdas de arco frescas y sin secar usadas para atar al hombre fuerte; el mismo término aparece en el Salmo 11:2, donde los impíos ''ajustan su flecha en la cuerda''. En Job, la palabra pasa a designar sogas de tienda: ''¿No es arrancada su cuerda de tienda dentro de ellos?'' (Job 4:21). El árabe watarun (cuerda de arco, cuerda de laúd) y el etíope wetr (tendón, cuerda) confirman el núcleo semántico de algo tensado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3500', 'spa', 'Jeter (Yéter) — nombre propio que significa ''abundancia'', llevado por varios personajes del AT, incluyendo al hijo de Gedeón y al padre de Amasa.', 'Yéter (יֶתֶר, ''abundancia, excelencia'') es un nombre propio masculino compartido por al menos cinco individuos en el Antiguo Testamento. El más destacado es Jeter el ismaelita (también llamado Itra), padre del general de David, Amasa (1 Re 2:5; 1 Cr 2:17). Otro portador notable es el primogénito de Gedeón, demasiado joven para ejecutar a los reyes madianitas (Jue 8:20). El nombre también aparece en hombres de Judá (1 Cr 2:32; 4:17) y de Aser (1 Cr 7:38). Su significado, enraizado en la idea de excedente o preeminencia, es transparente en hebreo y se conecta con el nombre relacionado Jetro (יִתְרוֹ).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3503', 'spa', 'Jetro (Yitro) — suegro de Moisés, sacerdote de Madián, quien aconsejó el establecimiento del sistema judicial de Israel.', 'Jetro (יִתְרוֹ, Yitró) es el sacerdote madianita y suegro de Moisés, que aparece exclusivamente en la fuente elohísta de Éxodo. Apacentaba su rebaño en Horeb, donde Moisés encontró la zarza ardiente (Éx 3:1), y más tarde visitó el campamento israelita trayendo a la esposa e hijos de Moisés. Su contribución más perdurable fue aconsejar a Moisés que delegara la autoridad judicial en subordinados capaces (Éx 18:13–26), un pasaje que se convirtió en fundamento de la gobernanza israelita. El nombre es una forma extendida de Yéter (יֶתֶר, H3500), que significa ''su abundancia''. La Septuaginta traduce consistentemente Ιοθορ en las nueve ocurrencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3504', 'spa', 'Provecho, ventaja, ganancia — el beneficio neto o superávit del trabajo o la sabiduría; término exclusivo de Qohélet', 'Este sustantivo, que aparece únicamente en Eclesiastés, recoge la pregunta emblemática de Qohélet: ¿qué ganancia duradera obtiene el ser humano bajo el sol? Funciona casi como un término de contabilidad comercial: el superávit neto una vez computado todo esfuerzo. Qohélet lo emplea diez veces para interrogar cada empresa humana, desde el trabajo agotador (1:3; 3:9) hasta la búsqueda de la sabiduría misma (2:13; 7:12). La evidencia multilingüe es notablemente consistente: el español ''provecho/ventaja'', el francés ''profit'' y el alemán ''Vorteil'' convergen en la idea de beneficio material, confirmando que Qohélet enmarca las cuestiones más profundas de la vida en el lenguaje del mercado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3505', 'spa', 'El yitrita, gentilicio que designa a miembros de un clan de Quiriat-jearim en Judá', 'הַיִּתְרִי (''el yitrita'') es un adjetivo gentilicio que aparece siempre con el artículo definido, identificando a miembros de un clan vinculado a Quiriat-jearim en Judá (1 Cr 2:53). Dos de los valientes de David, Ira y Gareb, son llamados yitritas en las listas paralelas de héroes de 2 Samuel 23:38 y 1 Crónicas 11:40. La Septuaginta traduce el nombre de diversas formas (Αιθειραιος, Ηθηρει), lo que refleja la fluidez habitual de los nombres propios en la transmisión griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3506', 'spa', 'Yitrán, nombre propio (edomita, aserita)', 'Nombre propio que designa a dos individuos distintos en listas genealógicas: un descendiente edomita de Seír el horeo (Génesis 36:26 = 1 Crónicas 1:41) y un hombre de la tribu de Aser (1 Crónicas 7:37, posiblemente idéntico al Jéter mencionado antes en la genealogía). La etimología del nombre es incierta, aunque podría relacionarse con la raíz יתר (quedar, sobrar, sobresalir). Las versiones griegas varían ampliamente (Ιθραν, Θερα, Ιεθερ), reflejando las dificultades habituales de transliterar nombres hebreos. Su uso tanto en linajes edomitas como israelitas demuestra que ciertos nombres traspasaban fronteras étnicas en el antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3508', 'spa', 'Lóbulo/apéndice del hígado — el lóbulo caudado, protuberancia grasa quemada en el ritual sacrificial israelita', 'El sustantivo יֹתֶרֶת (yothereth) designa el apéndice o lóbulo del hígado, casi con certeza el lóbulo caudado, una proyección grasa fácilmente separable durante el despiece. Aparece exclusivamente en instrucciones sacrificiales, siempre en la frase «el yothereth sobre el hígado» (הַיֹּתֶרֶת עַל הַכָּבֵד). Este lóbulo se quemaba sobre el altar como parte de las porciones grasas ofrecidas a YHWH en holocaustos, ofrendas de paz y ofrendas por el pecado (Éx 29:13, 22; Lv 3:4, 10, 15; 4:9; 7:4; 8:16, 25; 9:10, 19). Su inclusión constante junto a los riñones y la cola grasa refleja la preocupación sacerdotal por especificar exactamente qué grasas viscerales pertenecían a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3510', 'spa', 'Sentir dolor o causar dolor; angustia física, aflicción emocional o (por extensión) ruina y destrucción', 'Un verbo arraigado en la experiencia cruda del dolor, tanto corporal como emocional. En Génesis 34:25 los hombres de Siquem todavía están ''adoloridos'' por la circuncisión, y en Proverbios 14:13 el corazón mismo duele bajo la risa. El causativo Hifil convierte al que sufre en agente: Dios ''hiere pero también venda'' (Job 5:18), y las falsas profetisas ''entristecieron'' al justo a quien el SEÑOR no había afligido (Ez 13:22). Una extensión notable aparece en 2 Reyes 3:19, donde el verbo significa ''arruinar'' o ''dañar'' buena tierra — dolor infligido no sobre la carne sino sobre el paisaje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3511', 'spa', 'Dolor, angustia — tanto sufrimiento físico como profunda aflicción emocional, especialmente en Job, Isaías y Jeremías.', 'Sustantivo masculino (כְּאֵב) que expresa el dolor en toda su amplitud, desde la agonía física más cruda hasta la angustia emocional más aplastante. En Job captura ambas dimensiones: los amigos permanecieron en silencio porque ''el dolor era muy grande'' (Job 2:13), y el propio Job clama que hablar no alivia su dolor (Job 16:6). Los libros proféticos agudizan el término hacia el luto nacional: Isaías 17:11 habla de un dolor incurable en el día de la cosecha, una devastadora inversión de la esperanza agrícola. Isaías 65:14 contrasta el clamor de un espíritu quebrantado (כְּאֵב לֵב, ''dolor de corazón'') con el canto de los siervos de Dios. Jeremías 15:18 lo empareja con una herida que no sana. El Salmo 39:2 completa el cuadro con el sufrimiento silencioso del salmista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3512a', 'spa', 'Desanimarse, acobardarse, quebrarse de espíritu; perder el valor', 'Verbo que expresa el estado de desánimo, abatimiento o quebranto interior. En la forma nifal aparece en el Salmo 109:16 describiendo a un perseguido que es «quebrantado de corazón» (נִכְאֵה לֵבָב), en paralelo con «pobre y menesteroso». Daniel 11:30 lo emplea para un rey que «se acobarda» al fracasar su expedición naval. El infinitivo hifil de Ezequiel 13:22 (si la lectura es correcta) significaría «desanimar» o quebrantar el espíritu de los justos, aunque la Septuaginta y el Tárgum sugieren leer כָּאַב (causar dolor, entristecer). La raíz se relaciona con voces árabes que denotan retroceder tímidamente o abstenerse por temor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3513', 'spa', 'Ser pesado; honrar, respetar; ser honrado, glorificado; hacer pesado, endurecer; ser/hacer glorioso; ser rico', 'En su núcleo, esta raíz significa «ser pesado» en sentido físico: manos, yugos, hambruna, batalla. De ese significado concreto irradia un campo semántico riquísimo: honrar a los padres o a Dios (tratarlos como «pesados», es decir, dignos de peso), ser honrado o glorificado (tener peso o sustancia), endurecer el corazón (hacerlo pesado e insensible), e incluso ser acaudalado (cargado de posesiones). El Piel honra activamente, el Nifal expresa ser honrado, el Hifil hace pesado o endurece. El árabe كَرَّمَ marca el sentido honorífico, mientras que أَثْقَلَ captura la carga física y metafórica. La doble trayectoria semántica — el peso que conduce al honor y el peso que conduce a la carga — estructura todo el campo léxico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3514', 'spa', 'pesadez, peso; masa, abundancia; vehemencia, intensidad', 'Este sustantivo, derivado de la raíz común כבד (''ser pesado''), aparece en contextos que describen peso físico, cantidades masivas o fuerza intensa. Una piedra tiene ''peso'', los cadáveres se acumulan en ''masa'', una tormenta llega con ''vehemencia'' y la guerra presiona con ''intensidad'' abrumadora. El término capta la cualidad opresiva o aplastante que transmite la pesadez, ya sea en sentido literal o figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3515', 'spa', 'Pesado, grave; severo, penoso; oneroso; por extension, abundante o numeroso', 'Pesado, grave; severo, penoso; oneroso; por extension, abundante o numeroso');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3516', 'spa', 'Hígado; el órgano corporal, referido en el ritual sacrificial, la adivinación y como sede de emociones intensas', 'El sustantivo kaved como forma sustantivada designa el hígado, el órgano interno más grande y uno considerado en todo el antiguo Cercano Oriente como sede de sentimientos profundos. La raíz kbd significa ''pesado,'' y el hígado fue nombrado así por ser el órgano más pesado — conexión preservada en los cognados árabe kabid y arameo kabda. La mayoría de las apariciones se encuentran en la legislación sacrificial sacerdotal, donde el ''apéndice del hígado'' (yoteret ha-kaved) se quema sobre el altar (Éx 29:13, 22; Lv 3-9). Ezequiel 21:26 registra al rey de Babilonia consultando el hígado en la hepatoscopia. Proverbios 7:23 describe una flecha que atraviesa el hígado, y Lamentaciones 2:11 lo derrama en angustia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3518', 'spa', 'Apagarse o extinguirse (de fuego/lámpara); en Piel, apagar o extinguir activamente', 'Apagarse o extinguirse (de fuego/lámpara); en Piel, apagar o extinguir activamente');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3519', 'spa', 'Gloria, honor, esplendor; la radiancia visible de la presencia de Dios, la dignidad y estima humana, o la riqueza material', 'כָּבוֹד deriva de la raíz k-b-d que significa «ser pesado, tener peso», y ese peso etimológico impregna cada uso del sustantivo. En su acepción más elevada, denota la manifestación visible y luminosa de la presencia de Dios — el kavod que llena el tabernáculo (Éx 40:34), se asienta sobre el Sinaí (Éx 24:16) y abandona el templo en la devastadora visión de Ezequiel (Ez 10:18). Sin embargo, la misma palabra describe el honor terrenal, la posición social e incluso la prosperidad material, como cuando los hijos de Labán se quejan de que Jacob ha adquirido todo el kavod de su padre (Gn 31:1). El alemán Herrlichkeit y el español gloria rastrean el sentido de majestad divina, mientras que el francés richesse y el árabe ثروة aparecen cuando se trata de riqueza, confirmando que el hebreo antiguo reunía estos significados bajo un solo «techo pesado» de un modo que pocos idiomas modernos replican.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3524', 'spa', 'Poderoso, grande, fuerte; aplicado a personas, a Dios, a fuerzas naturales o a la abundancia — sinónimo poético de ''grande''', 'Adjetivo marcadamente poético que aparece casi exclusivamente en Job e Isaías, y funciona como sinónimo solemne de ''grande'' o ''poderoso''. Describe a Dios como el ''justo poderoso'' (Job 34:17), a guerreros formidables (Job 34:24) y a fuerzas naturales abrumadoras como ''aguas impetuosas'' (Isa 17:12, 28:2). Bildad lo emplea memorablemente para un ''viento impetuoso'' al caracterizar las palabras de Job (Job 8:2). En un caso se inclina hacia la cantidad pura — ''mi mano había adquirido mucho'' (Job 31:25) — donde ''abundante'' distingue este sentido económico de la idea de poder personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3526', 'spa', 'Lavar o limpiar prendas pisoteándolas o amasándolas en agua; el oficio profesional del batanero de limpiar telas.', 'Lavar o limpiar prendas pisoteándolas o amasándolas en agua; el oficio profesional del batanero de limpiar telas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3528', 'spa', 'Ya; adverbio de tiempo pasado que indica que algo ha ocurrido previamente, usado exclusivamente en Eclesiastés.', 'El adverbio כְּבָר (kevar) significa ''ya'' y es un rasgo distintivo del vocabulario del hebreo bíblico tardío propio de Eclesiastés. Aparece nueve veces, todas dentro de las reflexiones filosóficas de Qohélet sobre la naturaleza cíclica de la existencia. La célebre declaración ''no hay nada nuevo bajo el sol — ya ha sido'' (Ecl 1:10) capta su uso característico. La palabra enfatiza la culminación previa o la realidad ya establecida, reforzando el tema de Qohélet de que todo se repite. Común en el hebreo mishnaico y atestiguado en arameo y siríaco, su restricción a Eclesiastés dentro de la Biblia es uno de los marcadores más claros del perfil lingüístico tardío de ese libro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3529', 'spa', 'Quebar — río o canal en Babilonia junto al cual se asentaron los exiliados judíos y donde Ezequiel recibió sus visiones.', 'Quebar (כְּבָר) es el nombre de un río o canal en Babilonia, que aparece siempre en la frase fija nehar Kevar (''el río Quebar''). Este curso de agua constituye el escenario de todo el ministerio profético de Ezequiel: junto a él recibió su visión inaugural del carro divino (Ez 1:1, 3), permaneció atónito entre los exiliados durante siete días (3:15) y contempló la gloria del SEÑOR (3:23; 10:15, 20, 22; 43:3). Aunque la identificación exacta sigue siendo incierta —posiblemente el canal nāru kabari cerca de Nippur—, su mención reiterada ancla las visiones de Ezequiel en un lugar concreto del exilio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3530', 'spa', 'Trecho de tierra, cierta distancia; distancia corta (medida exacta incierta)', 'Sustantivo femenino que designa una medida de distancia, y aparece únicamente en la frase כִּבְרַת אֶרֶץ / כִּבְרַת הָאָרֶץ («un trecho de tierra»). Génesis 35:16 y 48:7 lo usan para describir la distancia que faltaba para llegar a Efrata/Belén cuando Raquel murió al dar a luz a Benjamín: «cuando aún faltaba un trecho de tierra para llegar a Efrata». En 2 Reyes 5:19 indica la distancia que Naamán recorrió desde Eliseo antes de regresar. La medida exacta es incierta, pero el contexto de 2 Reyes sugiere que era relativamente corta, quizás unas pocas millas o lo que alcanza la vista. En acadio, kibrâti significa un territorio extenso o un cuadrante del mundo, pero el uso hebreo parece mucho más modesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3532', 'spa', 'Cordero, oveja joven macho — primordialmente animal sacrificial en la ley levítica; también en símiles proféticos de inocencia', 'כֶּבֶשׂ es el término hebreo estándar para una oveja joven macho y aparece de manera abrumadora en la legislación ritual de Éxodo, Levítico y Números. Designa al animal del holocausto diario (Éx 29:38), la ofrenda por el pecado (Lv 4:32), los ritos de purificación (Lv 14:10) y cada calendario festivo de Números 28-29. Sin embargo, la palabra se libera de las listas cultuales en dos pasajes proféticos donde se convierte en símil de vulnerabilidad desgarradora: Jeremías «como cordero manso llevado al degolladero» (Jer 11:19) y el Israel descarriado de Oseas «como cordero en amplia pradera» (Os 4:16). Las traducciones emplean universalmente cordero/agneau/Lamm para ambos sentidos, dejando que el contexto transmita el paso de lo ritual a lo retórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3533', 'spa', 'Someter, conquistar o esclavizar; abarca desde el dominio sobre la creación hasta la conquista militar, la esclavitud y la violación sexual.', 'Someter, conquistar o esclavizar; abarca desde el dominio sobre la creación hasta la conquista militar, la esclavitud y la violación sexual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3535', 'spa', 'Corderita — oveja joven hembra, utilizada en regulaciones sacrificiales y memorablemente en la parábola de Natán a David.', 'Este sustantivo femenino designa una corderita, la contraparte hembra joven de כֶּבֶשׂ (cordero macho). Aparece en dos contextos profundamente memorables. En Génesis 21:28-30, Abraham aparta siete corderitas como testigos de su pacto con Abimelec en Beerseba, y el nombre mismo del lugar se deriva de este acto. En 2 Samuel 12:3-6, la parábola de Natán sobre la única corderita del pobre, criada como una hija, es una de las historias más emotivas de la Escritura, que convence a David de su pecado. La palabra también aparece en la legislación sacrificial: la ofrenda de purificación (Lv 14:10) y el voto nazareo (Nm 6:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3536', 'spa', 'horno, calera (para quemar cal o cocer cerámica)', 'Este sustantivo designa un horno o calera utilizado para cocer cerámica o quemar cal. El humo que se eleva de dicho horno sirve como vívido símil en las descripciones bíblicas: el humo de Sodoma y Gomorra subió ''como el humo de un horno'', y el monte Sinaí humeaba ''como el humo de un horno'' cuando Dios descendió sobre él. Las cenizas de un horno también figuran en el relato de las plagas, donde Moisés las esparció hacia el cielo para producir úlceras sobre los egipcios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3537', 'spa', 'Cántaro o tinaja de barro usada para acarrear agua, almacenar harina u otras provisiones', 'Cántaro o tinaja de barro usada para acarrear agua, almacenar harina u otras provisiones');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3540', 'spa', 'Quedorlaomer, rey de Elam que encabezó una coalición de cuatro reyes contra las ciudades de la llanura', 'Quedorlaomer (del acadio Kudur-Lagamar, ''siervo de la deidad Lagamaru'') fue el rey de Elam que lideró una alianza de cuatro reyes orientales en Génesis 14. Sometió a los cinco reyes de la llanura del Jordán durante doce años hasta que estos se rebelaron, lo que provocó una campaña punitiva en la cual Lot fue capturado. El rescate de Lot por parte de Abraham frente a las fuerzas de Quedorlaomer constituye una de las acciones militares más decisivas del patriarca. El origen elamita del nombre subraya el alcance internacional de la narración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3541', 'spa', 'Adverbio demostrativo: así, de este modo; también espacial «aquí/allí»; raramente temporal «ahora»', 'כֹּה es un adverbio demostrativo pequeño pero versátil que con mayor frecuencia significa «así» o «de este modo», introduciendo el contenido de un mensaje o decreto — de manera suprema en la fórmula profética del mensajero כֹּה אָמַר יְהוָה, «así dice el SEÑOR». El español así, el francés ainsi y el alemán so convergen en esta fuerza demostrativa de manera. Sin embargo, la palabra conserva un sentido espacial más antiguo, «aquí» o «allí», visible en la expresión pareada כֹּה וָכֹּה («aquí y allá, de un lado a otro», Éx 2:12). Una ocurrencia única en Éx 7:16 puede tener fuerza temporal: «hasta ahora».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3543a', 'spa', 'kahah -- oscurecerse, debilitarse; de ojos que pierden vista, fuego que mengua o espíritu que desfallece', 'El verbo kahah expresa el oscurecimiento o debilitamiento gradual de algo que fue brillante o vigoroso. Su aplicación principal es a los ojos que se oscurecen con la edad: los ojos de Isaac estaban demasiado oscurecidos para ver (Gn 27:1), pero notablemente, el ojo de Moisés ''no se oscureció'' ni a los 120 años (Dt 34:7). Job lamenta que su ojo ''se ha oscurecido de dolor'' (Job 17:7). En Zacarías 11:17, el ojo del pastor inútil será ''completamente oscurecido'' — juicio divino expresado mediante el mismo vocabulario de la vista que falla. La palabra se extiende más allá de la visión: el Siervo del Señor ''no desfallecerá'' (Is 42:4), y en Ezequiel 21:7 ''todo espíritu desfallecerá''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3544', 'spa', 'Tenue, apagado, desvanecido — describe brillo disminuido en ojos, marcas cutáneas, llamas o espíritu figurado.', 'El adjetivo כֵּהָה describe algo que ha perdido su intensidad o viveza, ya sea luz, color o vitalidad. Su uso más frecuente se encuentra en las leyes levíticas sobre enfermedades cutáneas, donde el sacerdote examina si una marca sospechosa se ha ''desvanecido'' o atenuado (Lv 13:6, 21, 26, 28, 39, 56), lo cual indica que la afección está sanando en lugar de extenderse. Fuera de Levítico, describe la vista debilitada de Elí (1 S 3:2), una mecha que arde tenuemente y que el Siervo no apagará (Is 42:3), y un espíritu abatido que se cambia por un manto de alabanza (Is 61:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3546', 'spa', 'poder, ser capaz (equivalente arameo del hebreo יכל)', 'Este verbo arameo, equivalente directo del hebreo יכל, expresa capacidad o habilidad. En los capítulos arameos de Daniel, aparece en contextos donde la sabiduría humana resulta insuficiente: los sabios no ''pueden'' revelar el sueño de Nabucodonosor ni leer la escritura en la pared. La forma participial funciona casi como adjetivo, describiendo a alguien como ''capaz'' de realizar una tarea, generalmente seguida de un infinitivo que especifica lo que pueden o no pueden hacer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3547', 'spa', 'Servir o ministrar como sacerdote; por extensión, adornarse a la manera sacerdotal (Isa 61:10).', 'Servir o ministrar como sacerdote; por extensión, adornarse a la manera sacerdotal (Isa 61:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3548', 'spa', 'Sacerdote — persona consagrada para ofrecer sacrificios, oficiar rituales y mediar entre Dios y el pueblo', 'El כֹּהֵן servía de puente entre lo divino y lo humano: oficiaba en el altar, manipulaba los objetos sagrados, pronunciaba bendiciones y dirimía cuestiones de pureza. Con 750 apariciones, el término designa abrumadoramente al sacerdocio levítico instituido en el Sinaí, aunque también se aplica a Melquisedec (Gn 14:18), a sacerdotes extranjeros como los de Dagón (1 S 5:5) y al rey-sacerdote mesiánico del Salmo 110:4. Las traducciones multilingües —''el sacerdote'', ''le sacrificateur'', ''der Priester''— coinciden en el sentido de oficiante cultual, lo que confirma un perfil semántico unitario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3549', 'spa', 'Sacerdote; sustantivo arameo para un funcionario religioso cúltico que ministra en el servicio del templo.', 'Sustantivo arameo que designa a un sacerdote o funcionario religioso, que aparece exclusivamente en los libros postexílicos de Esdras y Daniel. En Esdras, el término surge en correspondencia oficial y en la narrativa sobre el templo reconstruido, refiriéndose tanto a individuos específicos (''el sacerdote'' Esdras, Esd 7:12, 21) como a la comunidad sacerdotal colectivamente (''los sacerdotes'', Esd 6:9, 16, 18). La forma plural determinada kahnayyaʾ y la forma sufijada kohohi (''sus sacerdotes'') reflejan el hebreo bíblico כֹּהֵן con morfología aramea imperial estándar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3550', 'spa', 'Sacerdocio; el oficio, la función y el derecho hereditario del servicio sacerdotal en el culto de Israel.', 'Sacerdocio; el oficio, la función y el derecho hereditario del servicio sacerdotal en el culto de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3553', 'spa', 'Casco o yelmo — pieza de armadura militar de bronce para la batalla; usado figuradamente del ''yelmo de salvación'' de Dios en Isaías 59:17.', 'Sustantivo masculino (כּוֹבַע) que designa un casco o yelmo, pieza protectora usada por los soldados en la guerra del antiguo Cercano Oriente. Cinco de sus seis apariciones son militares: Goliat portaba un casco de bronce (1 Sam 17:5), Uzías equipó su ejército con yelmos (2 Cr 26:14), se ordena a los egipcios pulir sus cascos (Jer 46:4), y los mercenarios de Tiro cuelgan yelmos en su arsenal (Ez 27:10; 38:5). La sexta transforma la imagen teológicamente: en Isaías 59:17, Dios se reviste de un ''yelmo de salvación'', imagen que Pablo aplica a los creyentes (Ef 6:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3556', 'spa', 'estrella — cuerpo celeste luminoso, usado literalmente del cielo nocturno y figuradamente para multitud o realeza', 'estrella — cuerpo celeste luminoso, usado literalmente del cielo nocturno y figuradamente para multitud o realeza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3557', 'spa', 'Contener, sostener; sustentar, alimentar, proveer; soportar, resistir — de כּוּל ''medir, abarcar''', 'Contener, sostener; sustentar, alimentar, proveer; soportar, resistir — de כּוּל ''medir, abarcar''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3559a', 'spa', 'Preparar, disponer; ser/hacer firme, establecido; estar listo/ser correcto/cierto; dirigir, apuntar', 'Esta raíz expresa firmeza y preparación a través de múltiples conjugaciones. En el Hifil significa preparar o establecer activamente algo: una comida, un trono, un reino. El Nifal describe el estado de estar establecido, mantenerse firme o estar listo para la acción, así como lo que es correcto o cierto. Las formas Piel y Pual intensifican la acción de establecer o confirmar, mientras que algunas acepciones cubren la idea de dirigir o apuntar hacia un objetivo. El Hitpael reflexivo muestra el autoestablecimiento, como edificar una ciudad o prepararse a sí mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3562', 'spa', 'Konanyahu (Conanías), oficial levítico encargado de los diezmos y ofrendas en tiempos de Ezequías y Josías.', 'Nombre propio levítico que significa ''Yahveh ha establecido'', portado por al menos uno (posiblemente dos) personajes en Crónicas. El Konanyahu más destacado sirvió bajo el rey Ezequías como jefe supervisor de los diezmos, contribuciones y cosas consagradas que se llevaban al templo (2 Cr 31:12-13). Un segundo Konanyahu aparece entre los jefes levíticos que contribuyeron ganado para la gran celebración de la Pascua de Josías (2 Cr 35:9). El elemento teofórico -yahu afirma el establecimiento divino, algo apropiado para funcionarios encargados de administrar lo consagrado a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3563a', 'spa', 'Copa, cáliz — un recipiente para beber; figuradamente, la porción o destino asignado por Dios.', 'Copa, cáliz — un recipiente para beber; figuradamente, la porción o destino asignado por Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3563b', 'spa', 'Mochuelo (especie pequeña de búho), ave impura que habita en ruinas', 'Nombre de ave que designa una especie de búho pequeño, distinto del búho mayor (יַנְשׁוּף). Aparece entre las aves impuras en Levítico 11:17 y Deuteronomio 14:16, y en el Salmo 102:7 donde el salmista doliente se compara con «un búho de las ruinas», criatura solitaria que habita lugares desolados. La palabra podría ser onomatopéyica, imitando el canto del ave (de ahí כּוֹס). Aunque comparte las mismas consonantes que la palabra común para «copa» (כּוֹס I), se reconoce como un lexema distinto por el contexto y las versiones antiguas, que la interpretan unánimemente como un ave. La asociación del búho con las ruinas lo convirtió en una potente metáfora de soledad y desolación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3564', 'spa', 'Horno de fundición o crisol, usado casi exclusivamente como metáfora de aflicción, prueba y purificación divina.', 'El sustantivo כּוּר se refiere a un horno de fundición o crisol utilizado para refinar metales, pero en el uso bíblico funciona casi enteramente como metáfora. Egipto es llamado ''el horno de hierro'' del cual Dios sacó a Israel (Dt 4:20; 1 R 8:51; Jr 11:4), evocando el sufrimiento intenso de la esclavitud. Proverbios lo empareja con el crisol del refinador: ''El horno para el oro, el crisol para la plata, y el SEÑOR prueba los corazones'' (Pr 17:3; 27:21). Ezequiel retrata a Israel como escoria de metales arrojada al כּוּר de Dios (Ez 22:18-22), mientras Isaías habla de ser refinado ''en el horno de la aflicción'' (Is 48:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3566', 'spa', 'Ciro (כּוֹרֶשׁ) — rey de Persia que conquistó Babilonia y decretó el retorno judío del exilio.', 'Ciro (כּוֹרֶשׁ) — rey de Persia que conquistó Babilonia y decretó el retorno judío del exilio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3567', 'spa', 'Ciro; el emperador persa que autorizó el regreso de los exiliados judíos y la reconstrucción del templo.', 'Nombre propio Koresh (Ciro), en referencia a Ciro II (el Grande), fundador del Imperio persa aqueménida, quien conquistó Babilonia en el 539 a.e.c. y promulgó el edicto que permitió a los judíos regresar y reconstruir el templo de Jerusalén. Las ocho apariciones del nombre se concentran en Esdras y Daniel, donde se lo presenta como instrumento del propósito divino. Las distintas traducciones — español Ciro, francés Cyrus, alemán Koresch/Kyrus — reflejan el paso del nombre por el griego Kyros desde el persa antiguo Kuruš.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3568a', 'spa', 'Cus — la tierra y el pueblo al sur de Egipto (Nubia/Etiopía), e hijo de Cam en la Tabla de las Naciones.', 'Cus — la tierra y el pueblo al sur de Egipto (Nubia/Etiopía), e hijo de Cam en la Tabla de las Naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3569', 'spa', 'Cusita — persona o pueblo de la tierra de Cus (Etiopía/Nubia bíblica), usado como gentilicio sustantivo o adjetivo.', 'Cusita — persona o pueblo de la tierra de Cus (Etiopía/Nubia bíblica), usado como gentilicio sustantivo o adjetivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3573', 'spa', 'Cusán-Risataim, rey de Aram-Naharaim que oprimió a Israel durante ocho años', 'Cusán-Risataim aparece como el primer opresor extranjero en el libro de Jueces, un rey de Aram-Naharaim (Mesopotamia) a quien Dios entregó a Israel por su idolatría. Su nombre inusual, que podría significar ''Cusán de doble maldad'', intriga a los estudiosos, ya que ningún registro extrabíblico confirma su existencia. Gobernó sobre Israel durante ocho años hasta que Dios levantó a Otoniel para liberarlos. Es posible que el nombre sea un epíteto despectivo hebreo y no el nombre real del rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3576', 'spa', 'Mentir, engañar o resultar falso; en diversas formas verbales: decir mentiras (Piel), ser hallado mentiroso (Nifal), probar la falsedad de alguien (Hi', 'Mentir, engañar o resultar falso; en diversas formas verbales: decir mentiras (Piel), ser hallado mentiroso (Nifal), probar la falsedad de alguien (Hifil) o fallar/decepcionar (de cosas)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3577', 'spa', 'Mentira, falsedad — una declaración deliberadamente falsa o engañosa, especialmente en contextos proféticos y sapienciales.', 'Mentira, falsedad — una declaración deliberadamente falsa o engañosa, especialmente en contextos proféticos y sapienciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3581b', 'spa', 'Fuerza, poder, vigor; capacidad física o facultad para actuar; también riqueza o recursos derivados de la propia fuerza', 'כֹּחַ es la palabra más directa del hebreo bíblico para designar la fuerza bruta y el poder. Ya se trate de la legendaria fuerza física de Sansón (Jue 16:5-30), del vigor juvenil (Pr 20:29) o del poder divino detrás de la creación (Jr 10:12), esta voz apunta a una fuerza que se ejerce o se posee. Se distingue de גְּבוּרָה (poderío heroico) y de עֹז (fortaleza fortificada) por mantenerse más cerca de la capacidad y la energía básicas. La evidencia multilingüe es reveladora: el árabe quwwa, el coreano 힘 y el alemán Kraft convergen en el polo de fuerza física, mientras que un grupo menor — árabe al-qudra, coreano 능력 — señala una acepción diferenciada de capacidad o competencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3582', 'spa', 'Ocultar, esconder o negar conocimiento (Piel); ser ocultado o borrado (Nifal); aniquilar o exterminar (Hifil)', 'Ocultar, esconder o negar conocimiento (Piel); ser ocultado o borrado (Nifal); aniquilar o exterminar (Hifil)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3584', 'spa', 'Negar, mentir, obrar con falsedad; someterse fingidamente; fallar o defraudar; enflaquecer o consumirse.', 'Negar, mentir, obrar con falsedad; someterse fingidamente; fallar o defraudar; enflaquecer o consumirse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3585', 'spa', 'Mentira, engaño, traición (falsedad moral, especialmente la infidelidad de Israel); flaqueza, demacración (delgadez física).', 'El sustantivo כַּחַשׁ presenta una notable divergencia semántica. En cinco de sus seis apariciones designa un fallo moral — mentira, engaño, traición — concentrado en las acusaciones de Oseas contra Israel. Oseas 10:13 acusa al pueblo de comer ''el fruto de la mentira'', mientras que 7:3 y 11:12 catalogan sus engaños. Nahúm 3:1 extiende el vocabulario a Nínive, ''ciudad llena de mentira'', y el Salmo 59:12 lo empareja con la maldición. Sin embargo, Job 16:8 despliega un sentido distinto: ''mi flaqueza se levanta contra mí'', describiendo demacración física. El cognado targúmico confirma este segundo sentido genuino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3588a', 'spa', 'que; porque, pues; cuando; sino, más bien; si; ciertamente, en verdad; aunque, aun cuando', 'כִּי es la conjunción más versátil del hebreo bíblico, una auténtica navaja suiza de la subordinación. Su sentido causal (''porque, pues'') representa la inmensa mayoría de sus casi 4.300 apariciones, introduciendo la razón de lo que precede. Pero כִּי también funciona como completiva (''que'') tras verbos de ver, saber y decir —''vio Dios que era bueno'' (Gn 1:4)—. Más allá de estos dos pilares, marca cláusulas temporales (''cuando''), contrastes adversativos (''sino''), prótasis condicionales (''si''), afirmaciones enfáticas (''ciertamente'') e incluso concesiones (''aunque''). La estela moabita de Mesá emplea la misma partícula de modo idéntico, confirmando su honda raigambre semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3588b', 'spa', 'Conjunción compuesta כִּי אִם: sino/más bien (adversativa), excepto/a menos que (exceptiva), porque (causal), o ciertamente/que (aseverativa)', 'Formada por la conjunción כִּי y la partícula אִם unidas por maqqef, esta partícula compuesta desempeña funciones sorprendentemente distintas según el contexto. Tras una negación, suele significar ''sino'' o ''más bien'', corrigiendo lo anterior (Gn 32:28: ''No se dirá más tu nombre Jacob, sino Israel''). Cuando limita una afirmación general, señala ''excepto'' o ''a menos que'' (Gn 39:9: ''No me ha negado nada excepto a ti''). También puede introducir una razón (''porque si rehúsas'', Ex 10:4) o, más raramente, funcionar como un enfático ''ciertamente'' en fórmulas de juramento (1 S 14:39). Los traductores distinguen consistentemente estas funciones: español sino para la adversativa, francés sauf para la exceptiva y alemán denn para la causal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3588c', 'spa', 'Conjunción compuesta ''porque / por cuanto,'' que enfatiza pleonásticamente la razón causal', 'Esta locución distintiva kî ʿal kēn combina la conjunción kî (''porque'') con la expresión preposicional ʿal kēn (''por tanto, por esto''), creando un énfasis pleonástico — literalmente ''porque por-causa-de-esto''. Aparece en momentos narrativos clave donde el hablante quiere subrayar la razón detrás de una acción: Abraham instando a la hospitalidad (Gn 18:5), Lot protegiendo a sus huéspedes (Gn 19:8), el emotivo reencuentro de Jacob con Esaú (Gn 33:10). Las traducciones la reducen a un simple ''porque'', aunque el original hebreo conlleva una fuerza retórica más solemne y enfática de lo que transmite cualquier conjunción causal sencilla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3591', 'spa', 'Jabalina o lanza corta arrojadiza, arma militar distinta de la más larga חֲנִית (lanza de acometida).', 'El sustantivo כִּידוֹן designa una jabalina o lanza corta arrojadiza, que el hebreo distingue sistemáticamente de la חֲנִית, la lanza pesada de acometida. La palabra es célebre por el armamento de Goliat: llevaba una jabalina de bronce entre los hombros junto con su gran lanza (1 Sam 17:6, 45). Josué la empleó como arma de señal táctica, extendiéndola hacia Hai por mandato divino (Jos 8:18, 26). Jeremías y Job la asocian con otras armas en descripciones de terror bélico (Jer 6:23; 50:42; Job 39:23; 41:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3595', 'spa', 'Fuente o pila para lavamientos rituales; olla o brasero; plataforma de bronce.', 'Fuente o pila para lavamientos rituales; olla o brasero; plataforma de bronce.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3598', 'spa', 'Pléyades, cúmulo estelar mencionado como testimonio del poder creador de Dios (Job 9:9; 38:31; Amós 5:8)', 'Término astronómico hebreo que designa el cúmulo estelar de las Pléyades. Los escritores sapienciales y proféticos lo mencionan junto a otras constelaciones como Orión (כְּסִיל) para ilustrar el poder creador y la soberanía de Dios sobre el cosmos. En Job 38:31, Dios desafía a Job con preguntas retóricas sobre atar las cadenas de las Pléyades, subrayando que solo la autoridad divina gobierna el ámbito celestial. Amós 5:8 invoca este cúmulo al exaltar al Creador que transforma la oscuridad en amanecer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3599', 'spa', 'Bolsa o bolsillo para llevar dinero o pesas; usado tanto en el comercio honesto como en el deshonesto.', 'Se refiere a una bolsa pequeña o bolsillo que se llevaba encima, utilizado tanto para guardar pesas comerciales como dinero. En su uso más vívido, Proverbios 1:14 describe a los pecadores tentando a un joven con la promesa de una bolsa compartida, mientras que Miqueas 6:11 denuncia la ''bolsa de pesas engañosas'' usada para estafar en el mercado. Los cognados en las lenguas semíticas son notablemente consistentes — árabe kis, etiópico kis, arameo kisa — todos apuntando al mismo objeto cotidiano del comercio personal. Isaías 46:6 retrata a los idólatras derrochando oro de la bolsa para fabricar un ídolo inútil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3602', 'spa', 'asi, de esta manera — adverbio demostrativo de modo, ligeramente mas enfatico que koh', 'asi, de esta manera — adverbio demostrativo de modo, ligeramente mas enfatico que koh');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3603', 'spa', 'Algo redondo: un talento (unidad de peso, ~30 kg); una región redonda o llanura, especialmente el valle del Jordán; una hogaza redonda de pan.', 'Algo redondo: un talento (unidad de peso, ~30 kg); una región redonda o llanura, especialmente el valle del Jordán; una hogaza redonda de pan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3605', 'spa', 'Todo, todos, cada, cualquier; cuantificador universal que expresa totalidad, integridad o alcance distributivo.', 'Una de las palabras más frecuentes de la Biblia hebrea, כֹּל es el cuantificador universal que abarca la totalidad dentro de su alcance. Ya sea modificando un sustantivo (''toda la tierra'', ''cada criatura''), funcionando de manera independiente como ''todo'' (Ecl 1:2, ''todo es vanidad''), o distribuyendo entre individuos (''cada uno'', Ecl 3:1), insiste en la totalidad. En contextos negativos o condicionales adquiere el matiz de ''cualquier'' (Dt 4:15-18). La evidencia multilingüe es notablemente uniforme —español ''todos/toda'', francés ''tout'', alemán ''alle''— reflejando cómo cada lengua necesita el mismo alcance abarcador que esta pequeña palabra proporciona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3606', 'spa', 'Todo, cada, entero; cuantificador arameo que expresa totalidad, universalidad o distribución indefinida sobre una clase', 'Equivalente arameo del hebreo כֹּל, esta palabra satura las secciones arameas de Esdras y Daniel como marcador principal de totalidad y universalidad. Ya se trate de convocar a ''todos los sabios de Babilonia'' (Dn 2:12) o de decretar que ''todo pueblo, nación y lengua'' debe obedecer (Dn 3:29), כֹּל proporciona el alcance abarcador característico de los edictos reales y las declaraciones divinas. En su forma enfática (determinada) כֹּלָּא, funciona como sustantivo independiente con el sentido de ''todo, la totalidad'', en lugar de actuar como modificador. Los traductores recurren uniformemente a su cuantificador universal más fuerte: español todo, francés tout, alemán alle.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3607', 'spa', 'Encerrar, contener o retener; confinar o encarcelar; en forma pasiva, ser detenido o cesar', 'Encerrar, contener o retener; confinar o encarcelar; en forma pasiva, ser detenido o cesar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3608', 'spa', 'Encierro, prisión — lugar de encarcelamiento; usado en la frase bêth hakkelĕʾ ''casa de prisión''', 'Este sustantivo designa un lugar de encierro o reclusión, y aparece típicamente en la construcción bêth (hak)keleʾ, ''la casa de prisión''. Describe cárceles literales en los libros históricos y proféticos: donde Micaías fue recluido por Acab (1 R 22:27), donde Oseas fue encerrado por Asiria (2 R 17:4) y donde Jeremías sufrió detención repetida (Jer 37:15, 18). Isaías usa su plural bāttê kelāʾîm (''casas de encierro'', Isa 42:22) para describir la cautividad espiritual de Israel. El cognado acadio bīt kīli confirma que forma parte de un vocabulario compartido del antiguo Cercano Oriente para el encarcelamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3610', 'spa', 'dos especies, mezcla prohibida; especies diversas (vedadas en la ley levítica)', 'Este sustantivo en forma dual aparece exclusivamente en las leyes de santidad que prohíben la mezcla de especies diferentes. El término designa combinaciones vedadas: cruzar ganado de distintas especies, sembrar campos con semillas mezcladas o vestir prendas tejidas con dos tipos de hilo. La raíz hebrea se relaciona con «ambos» o «dos», subrayando la dualidad que la ley prohíbe. Estas prohibiciones buscaban preservar las distinciones del orden creado, enseñando a Israel a respetar los límites que Dios estableció en la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3611', 'spa', 'perro — canino domestico, frecuentemente asociado con la carroneria y usado figuradamente como termino de desprecio', 'perro — canino domestico, frecuentemente asociado con la carroneria y usado figuradamente como termino de desprecio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3612', 'spa', 'Caleb — el fiel espia cenezeo que siguio plenamente al SENOR y heredo Hebron', 'Caleb — el fiel espia cenezeo que siguio plenamente al SENOR y heredo Hebron');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3615', 'spa', 'Completar, terminar, llevar a su fin; consumir, destruir; faltar, agotarse; cumplir un propósito o decreto', 'Con 205 apariciones, este verbo abarca tanto la conclusión natural de tareas como el consumo exhaustivo o la destrucción de personas y cosas. Describe a constructores terminando el templo de Salomón, la ira de Dios consumiendo enemigos, provisiones que se agotan, ojos que desfallecen de llanto y decretos divinos determinados como definitivos. El espectro va desde la culminación neutra (terminar una obra, pasar los días) hasta el consumo violento (aniquilar naciones) y el agotamiento emocional (fuerzas o esperanza que decaen). Varios contextos emplean formas pasivas donde algo es completado o cumplido por un agente externo, subrayando la exhaustividad de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3617', 'spa', 'Destrucción completa, aniquilación; adverbialmente ''completamente''; decreto determinado de juicio.', 'Destrucción completa, aniquilación; adverbialmente ''completamente''; decreto determinado de juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3618', 'spa', 'Nuera o novia; mujer definida por su relacion matrimonial, ya sea como esposa de un hijo o como mujer en el dia de su boda', 'Nuera o novia; mujer definida por su relacion matrimonial, ya sea como esposa de un hijo o como mujer en el dia de su boda');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3619', 'spa', 'Canasta o jaula: recipiente de mimbre para contener aves o fruta de verano', 'Recipiente tejido de juncos o mimbre, empleado como jaula para aves o como canasta para fruta. Jeremías lo usa como potente metáfora del liderazgo corrupto de Jerusalén: así como una jaula rebosa de pájaros, la ciudad está repleta de engaño y ganancias injustas. Amós lo emplea de modo más literal para una canasta de fruta madura de verano, que se convierte en un juego de palabras visual sobre el fin inminente de Israel, pues קַיִץ (fruta de verano) suena como קֵץ (fin).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3627', 'spa', 'Vasija, utensilio, recipiente; arma, armadura; instrumento, artículo, herramienta; enseres, equipaje; instrumento musical', 'Uno de los sustantivos con mayor versatilidad semántica del hebreo, que abarca prácticamente cualquier objeto fabricado. Desde las vasijas sagradas del tabernáculo (Ex 27:19) hasta las armas de guerra (Gn 49:5), desde el morral de pastor de David (1 S 17:40) hasta los instrumentos de alabanza en el templo (1 Cr 15:16), כְּלִי deriva su amplitud de un sentido raíz de algo completado o contenido. El árabe reparte estas funciones entre varias palabras — إناء para vasijas, سلاح para armas, آلة para instrumentos —, revelando distinciones que el hebreo condensa en un solo lexema. El contexto y las cadenas constructas realizan la labor de desambiguación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3628', 'spa', 'prisión, lugar de encierro (variante Ketiv-Qere de כלא)', 'Esta palabra representa una variante textual (Ketiv frente a Qere) que significa «prisión», y aparece en los relatos de Jeremías sobre el encarcelamiento real. La expresión «casa de encierro» designa la prisión real donde se retenía a profetas y enemigos del estado. El propio Jeremías conoció tal cautiverio, al igual que Joaquín, último rey de Judá, quien pasó décadas en prisión babilónica antes de ser finalmente liberado y honrado en la mesa del rey de Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3629', 'spa', 'Rinones, tanto como organo fisico (especialmente en el ritual sacrificial) como sede de las emociones, la conciencia y el ser mas intimo', 'Rinones, tanto como organo fisico (especialmente en el ritual sacrificial) como sede de las emociones, la conciencia y el ser mas intimo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3630', 'spa', 'Quilión, uno de los dos hijos de Noemí (Rut 1:2, 5; 4:9)', 'Nombre de uno de los hijos de Elimélec y Noemí, hermano de Mahlón. Ambos hermanos se casaron con mujeres moabitas (Orfa y Rut), pero murieron sin descendencia en Moab durante los años de hambruna. La muerte prematura de Quilión prepara el escenario para la notable lealtad de Rut hacia Noemí y su eventual matrimonio con Booz, insertándola así en el linaje del rey David. Su nombre podría derivar de una raíz que sugiere «consumición» o «desgaste», presagiando su temprana muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3632', 'spa', 'Entero, completo, perfecto; como sustantivo: la totalidad de algo; holocausto completamente consumido por el fuego.', 'Entero, completo, perfecto; como sustantivo: la totalidad de algo; holocausto completamente consumido por el fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3635a', 'spa', 'Completar o terminar (arameo); usado exclusivamente para la finalización de la construcción del templo de Jerusalén y sus muros.', 'Verbo arameo que se encuentra únicamente en Esdras 4-6, donde describe la terminación de proyectos de construcción en la Jerusalén postexílica. Cada aparición se relaciona con la reconstrucción del templo o de los muros de la ciudad bajo autorización persa. La forma Shaf''el (causativa) transmite la idea de llevar activamente un proyecto a su finalización, mientras que el Ishtaf''el (pasivo-reflexivo) describe muros que ''son completados''. El español lo traduce acertadamente con terminar y completar. La palabra podría ser un préstamo del acadio suklulu (''llevar a la perfección''), vinculando el vocabulario administrativo babilónico con la narrativa de la reconstrucción en época persa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3637', 'spa', 'Avergonzarse, ser deshonrado (Nifal); humillar, poner en vergüenza (Hifil); ser causado vergüenza (Hofal)', 'Avergonzarse, ser deshonrado (Nifal); humillar, poner en vergüenza (Hifil); ser causado vergüenza (Hofal)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3639', 'spa', 'Vergüenza, ignominia, deshonra; insulto o reproche experimentado como humillación ante Dios o ante otros.', 'Vergüenza, ignominia, deshonra; insulto o reproche experimentado como humillación ante Dios o ante otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3643', 'spa', 'Quimam, servidor de David vinculado a Barzilai; también topónimo cerca de Belén', 'Quimam fue un hombre estrechamente asociado con Barzilai el galaadita, probablemente su hijo, a quien David incorporó a su séquito como recompensa por la lealtad de Barzilai durante la rebelión de Absalón (2 Sam 19:37-40). El nombre aparece también en Jeremías 41:17 como parte del topónimo compuesto Gerut Quimam, un lugar de hospedaje cerca de Belén donde los refugiados de Johanán se detuvieron camino a Egipto. La transición de nombre personal a topónimo sugiere que Quimam recibió una concesión de tierras cerca de Belén, detalle coherente con la promesa de David a Barzilai.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3644', 'spa', 'Como, a semejanza de; preposición comparativa poética y enfática, sinónima de la más simple כְּ, usada principalmente en verso', 'כְּמוֹ es la hermana más plena y enfática de la preposición hebrea común כְּ (''como''). Construida a partir de כְּ más el interrogativo מוֹ (''¿qué?''), literalmente significa algo así como ''a la semejanza de qué (es)…'' y aparece casi exclusivamente en poesía: 56 de sus 142 apariciones figuran como palabra independiente en versos poéticos, mientras que el resto funciona como equivalente poético de כְּ ante sufijos pronominales. El español como, el francés comme y el alemán wie la traducen de modo idéntico a כְּ simple, que es precisamente la clave: el contenido semántico es el mismo, pero el registro es elevado. Los cognados son reveladores: el arameo כְּמָא, el árabe كَمَا y el etíope kama preservan este compuesto comparativo, confirmando su profundo linaje semítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3645', 'spa', 'Quemos, deidad nacional de Moab, asociada con la idolatría y el juicio divino contra los dioses paganos.', 'Quemos era el dios principal de los moabitas, cuyo pueblo es llamado «pueblo de Quemos» en el antiguo cántico de Números 21:29. Salomón edificó notoriamente un lugar alto para Quemos en el monte al oriente de Jerusalén (1 Re 11:7), que Josías profanó durante sus reformas (2 Re 23:13). El nombre aparece en la Estela de Moab (Inscripción de Mesa) como la deidad a quien el rey moabita atribuía sus victorias militares, en paralelo con la manera en que Israel acreditaba a Yahvé. Jeremías 48:13 profetiza que Moab se avergonzará de Quemos, así como Israel se avergonzó del becerro de oro de Betel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3646', 'spa', 'Comino, semilla aromática usada como especia y condimento en el antiguo Israel', 'Hierba cultivada en el antiguo Israel por sus semillas de aroma penetrante, empleadas como condimento culinario. Isaías 28 describe las prácticas agrícolas relacionadas con el comino: cómo se siembra y se trilla con cuidado, golpeándolo con una vara en lugar de aplastarlo con un pesado trillo, a diferencia del grano. Esta imagen ilustra la sabiduría de Dios al adaptar sus métodos a la naturaleza de cada planta, y sirve como metáfora para asegurar a Judá que la disciplina divina es siempre proporcionada y medida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3648', 'spa', 'enternecerse, conmoverse (de compasión); arder, calentarse (de la piel en el hambre)', 'Este verbo describe el calentamiento o la agitación de emociones profundas, especialmente la compasión paternal, y también el ardor de la piel durante la hambruna. Cuando se usa con compasión (rahamim), capta la respuesta visceral y fisiológica de la ternura: el modo en que el corazón de un padre «se enternece» hacia su hijo, o cómo la compasión de Dios «se enciende» hacia su pueblo. En un uso físico notable, describe la piel ardiendo como un horno durante la fiebre del hambre. El cognado arameo significa calentar la carne o la comida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3649', 'spa', 'Sacerdote idólatra, sacerdote al servicio de dioses falsos en lugar de YHWH', 'Término que designa específicamente a los sacerdotes de cultos paganos, nunca aplicado a los sacerdotes levíticos legítimos. La reforma del rey Josías (2 Reyes 23:5) tuvo como blanco a estos clérigos idólatras que reyes anteriores habían nombrado para quemar incienso en los lugares altos. La palabra aparece en paralelo con los «sacerdotes» regulares (כֹּהֲנִים) en Sofonías 1:4, distinguiendo a los ilegítimos de aquellos que, aun sirviendo en el templo de Jerusalén, también se habían comprometido con el culto a Baal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3651a', 'spa', 'Correcto, recto, apropiado; como adverbio, así o de esta manera; de personas, honrado e íntegro.', 'Correcto, recto, apropiado; como adverbio, así o de esta manera; de personas, honrado e íntegro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3651b', 'spa', 'Por tanto, por esta razón — frase causal pleonástica que enfatiza el fundamento o motivo de una acción.', 'La frase compuesta כִּי עַל כֵּן significa literalmente «porque sobre así», una forma retóricamente enfática de decir «porque» o «por esta misma razón». Aparece en contextos narrativos donde el hablante subraya el fundamento de una acción, como cuando Abraham insta a sus visitantes celestiales a aceptar hospitalidad «pues por eso habéis pasado cerca de vuestro siervo» (Gn 18:5). La expresión tiene un carácter ligeramente arcaico y formal, y aparece en relatos patriarcales (Génesis 18, 19, 33, 38), narraciones del desierto (Números 10, 14) y discurso profético (Jeremías 29, 38).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3651c', 'spa', 'Así, de este modo; por tanto; esto, eso; entonces; ciertamente; en tal grado — adverbio de modo, causa y referencia.', 'Derivado de la raíz demostrativa כ (la misma raíz detrás de כִּי, ''porque/que''), este adverbio (כֵּן) es una de las palabras conectivas más versátiles del hebreo. En casi 500 de sus 734 apariciones significa simplemente ''así, de este modo'', describiendo manera: ''Dijo Dios... y fue así'' (Gn 1:7). Pero en más de 200 casos funciona como conectivo lógico con el significado de ''por tanto'', introduciendo la consecuencia de lo precedente. Usos menos frecuentes incluyen la referencia anafórica (''esta cosa''), el temporal ''entonces'', el enfático ''ciertamente'' y el de grado ''tanto''. Su carácter camaleónico lo convierte en palabra clave para rastrear la arquitectura lógica de la narrativa y la ley hebreas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3652', 'spa', 'Así, de este modo; adverbio arameo que introduce discurso directo o resume una declaración precedente.', 'Adverbio arameo que significa «así» o «de este modo», usado para introducir discurso directo o resumir lo que se ha declarado. Casi todas las apariciones se combinan con un verbo de decir (אֲמַר), formando la fórmula estándar aramea de introducción de discurso: «y así le dijo» (Dn 2:24). En Esdras 6:2, la variante «y así estaba escrito en él» extiende el uso a registros escritos. Cognado del hebreo bíblico כֵּן, el vocablo funciona de manera idéntica al español «así» en la estructura del discurso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3653', 'spa', 'Base, pedestal o soporte (especialmente del lavacro del tabernáculo); posición u oficio; asimismo, de igual manera', 'Base, pedestal o soporte (especialmente del lavacro del tabernáculo); posición u oficio; asimismo, de igual manera');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3654', 'spa', 'Mosquitos o piojos (la plaga de insectos de Egipto); también partícula adverbial ''así, de igual modo'' en Isa 51:6', 'Bajo esta entrada conviven dos palabras completamente distintas. La forma principal, כִּנִּים (kinnim), designa los diminutos insectos mordedores de la tercera plaga egipcia (Éx 8:16-18), identificados como mosquitos (Septuaginta, Vulgata y la mayoría de los estudiosos modernos) o como piojos (Targum, Josefo y la tradición rabínica posterior). El Sal 105:31 rememora esta plaga en lenguaje poético. La única aparición en Isa 51:6 corresponde a una palabra diferente: el adverbio כֵּן (ken), que significa ''así, de igual modo'', describiendo cómo los habitantes de la tierra perecerán de la misma manera que los cielos se desvanecen como humo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3655', 'spa', 'dar título, sobrenombre o epíteto (Piel); halagar con títulos honoríficos', 'Este verbo en la conjugación Piel significa otorgar un título, cognomen o sobrenombre a alguien. Isaías lo emplea cuando Dios declara que ha «dado un título» a Ciro, llamándolo por nombre antes de que Ciro conociera a Dios. El término puede tener fuerza honorífica, al conferir un título de honor, o bien un sentido negativo de halagar con títulos inmerecidos. Elihú insiste en que no «dará títulos aduladores» a ningún hombre, rechazando la práctica servil de otorgar honoríficos a los indignos. Los cognados arameo y árabe también se relacionan con sobrenombres y epítetos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3658', 'spa', 'Lira, arpa — el kinnor, instrumento de cuerdas portátil usado en la adoración, la celebración y el lamento', 'Lira, arpa — el kinnor, instrumento de cuerdas portátil usado en la adoración, la celebración y el lamento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3659', 'spa', 'Jeconías (también Conías, Joaquín), penúltimo rey de Judá, exiliado a Babilonia', 'Este lema representa una variante ortográfica (כָּנְיָהוּ) del nombre más conocido como Joaquín o Jeconías. El joven rey gobernó apenas tres meses antes de que Nabucodonosor lo deportara a Babilonia en el 597 a.C. Las profecías de Jeremías emplean la forma abreviada Conías con juegos de palabras, declarando que aunque fuera un anillo de sello en la mano de Dios, sería arrancado y entregado a Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3660', 'spa', 'Adverbio arameo: así, en consecuencia, de la siguiente manera, de este modo', 'Este adverbio arameo funciona como conector discursivo en la correspondencia oficial y la narrativa de Esdras, con el significado de ''en consecuencia'' o ''de la siguiente manera''. Puede señalar hacia atrás para resumir lo recién expresado (Esd 6:13, ''hicieron en consecuencia'') o hacia adelante para introducir el contenido de una carta o discurso (Esd 4:8, ''escribieron de la siguiente manera''). Su derivación es debatida —posiblemente de כֵּן (''así'') más una partícula indefinida מָא— pero su función pragmática como enlace textual es clara en todas sus apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3663', 'spa', 'Quenanías, músico levita y oficial en tiempos de David', 'Nombre levítico que significa ''YHWH ha establecido'' o ''YHWH es firme''. Dos personas llevan este nombre en Crónicas: un músico hábil designado por David para dirigir el canto cuando el arca fue trasladada a Jerusalén, y un levita izharita asignado a funciones externas como oficial y juez. El nombre en sí proclama confianza en la fidelidad y estabilidad de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3664', 'spa', 'Reunir, recoger (Qal); congregar con propósito (Piel); envolverse, arroparse (Hitpael)', 'Verbo del hebreo tardío para reunir y recoger, emparentado con el arameo kənas y el conocido término ''knesset'' (asamblea). En su forma básica Qal, abarca recoger piedras (Ec 3:5), amasar riquezas (Ec 2:8) y juntar provisiones para los levitas (Neh 12:44). El Piel intensifica el sentido hacia una congregación deliberada y divina: Dios reúne a los desterrados de Israel (Sal 147:2) y congrega a las naciones para juicio (Ez 22:21). Un Hitpael aislado en Isaías 28:20 cambia llamativamente hacia envolverse, cuando una cama demasiado corta obliga a arroparse apretadamente — un giro semántico tan singular que varias traducciones europeas apenas logran capturarlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3665', 'spa', 'Ser humillado o sometido; humillarse ante Dios; abatir por fuerza o acción divina', 'Ser humillado o sometido; humillarse ante Dios; abatir por fuerza o acción divina');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3667a', 'spa', 'Canaán — nieto de Noé y antepasado epónimo de los cananeos; la tierra prometida al oeste del Jordán; por metonimia, un comerciante.', 'Canaán — nieto de Noé y antepasado epónimo de los cananeos; la tierra prometida al oeste del Jordán; por metonimia, un comerciante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3667b', 'spa', 'mercader, comerciante (sentido secundario de Canaán, porque los cananeos/fenicios eran conocidos como comerciantes)', 'La palabra «Canaán» desarrolló un significado secundario de «mercader» o «comerciante» porque los cananeos, especialmente los fenicios, eran célebres como comerciantes en todo el antiguo Cercano Oriente. Ezequiel usa «tierra de Canaán» con el sentido de «tierra de mercaderes», y Sofonías habla de «todo el pueblo mercader» empleando la designación cananea. Esta extensión semántica muestra cómo los nombres étnicos pueden convertirse en designaciones profesionales cuando un pueblo domina un oficio o comercio particular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3668', 'spa', 'Quenaana, nombre propio del padre del profeta Sedequías y de un benjamita', 'Quenaana es un nombre propio hebreo portado por dos individuos. El más destacado es el padre de Sedequías, el profeta que fabricó cuernos de hierro y predijo dramáticamente la victoria de Acab en Ramot de Galaad (1 R 22:11, 24; 2 Cr 18:10, 23). El otro es un hijo de Bilhán enumerado entre los benjamitas (1 Cr 7:10). El nombre parece estar relacionado con ''Canaán'', y la Septuaginta lo traduce como Χανααν o Χαναναν, reforzando la conexión etimológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3669a', 'spa', 'Cananeo; miembro del pueblo preisraelita de Canaán; por extensión metonímica, un comerciante o mercader.', 'Cananeo; miembro del pueblo preisraelita de Canaán; por extensión metonímica, un comerciante o mercader.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3671', 'spa', 'Ala de ave, ángel o querubín; también la falda o borde de un vestido, o el extremo/confín de una tierra', 'כָּנָף es una de las palabras más evocadoras del hebreo, que transita fluidamente entre el ala literal de un ave (Dt 32:11), las alas protectoras de Dios cobijando a su pueblo (Sal 91:4), la falda de un vestido que se extiende sobre alguien como acto de protección pactual (Rt 3:9) y los confines de la tierra (Is 11:12). La misma voz que describe las alas desplegadas de los querubines de oro en el Lugar Santísimo (1 R 6:24) también designa las esquinas con flecos del manto israelita (Nm 15:38). Este campo semántico — de ala a borde, de borde a horizonte — revela cómo el hebreo antiguo trazó la extensión espacial a partir de una sola imagen corporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3672', 'spa', 'Kinnereth -- ciudad en Neftalí y su lago adyacente (el Mar de Galilea)', 'Kinnereth (también escrito Kinerot/Kinnerot) es un nombre propio geográfico que designa tanto una ciudad fortificada en el territorio tribal de Neftalí (Jos 19:35) como el lago de agua dulce adyacente, conocido posteriormente como el Mar de Galilea o Lago de Tiberíades. El nombre posiblemente derive de כִּנּוֹר (''arpa''), quizá por la forma de arpa del lago. Como יָם כִּנֶּרֶת (''Mar de Kinnereth'') aparece en Núm 34:11 y Jos 12:3; 13:27, marcando un punto clave en la delimitación de las asignaciones tribales. En 1 Re 15:20, ''toda Kinnerot'' se refiere al territorio circundante conquistado por Ben-hadad de Aram.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3673', 'spa', 'Reunir, congregar (raíz aramea usada en Daniel 3)', 'Verbo arameo que aparece únicamente en Daniel 3, describiendo la congregación de funcionarios para la ceremonia de dedicación de la imagen de Nabucodonosor. La forma hitpael enfatiza la acción de reunirse: oficiales de todo el imperio convergiendo ante la convocatoria del rey. Esta raíz es paralela al más frecuente hebreo כָּנַס, reflejando el desplazamiento lingüístico hacia el arameo en los períodos exílico y postexílico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3675', 'spa', 'kenat -- compañero, asociado; sustantivo arameo usado exclusivamente en Esdras para colegas oficiales', 'El sustantivo כְּנָת (''compañero, asociado'') pertenece al estrato arameo de la Biblia hebrea y aparece exclusivamente en el libro de Esdras, dentro de la correspondencia oficial entre funcionarios provinciales persas y la corte real. Las siete ocurrencias siguen el mismo patrón: un funcionario nombrado ''y sus compañeros'' (Esd 4:9, 17, 23; 5:3, 6; 6:6, 13). La palabra es cognada del arameo antiguo knt y posiblemente un préstamo del acadio kinatu (''asociado''). Su uso formulaico en cartas burocráticas le confiere un matiz casi técnico: no se trata de amigos casuales, sino de colegas oficiales que comparten autoridad administrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3678', 'spa', 'Asiento de honor o trono; sede real o divina de autoridad, y por extensión cualquier asiento de dignidad o juicio', 'כִּסֵּא es la palabra del hebreo bíblico para el asiento donde reside el poder. En la abrumadora mayoría de sus apariciones designa el trono real — de David, Salomón, Faraón o del mismo Dios — y con él la autoridad, la dinastía y la legitimidad que el trono representa. ''Tu trono, oh Dios, es eterno y para siempre'' (Sal 45:6) y ''Estableceré el trono de su reino para siempre'' (2 S 7:13) muestran cómo כִּסֵּא se convirtió en metonimia de la realeza misma. Los cognados semíticos son llamativos: el arameo כֻּרְסְיָא, el árabe كُرْسِيّ y el acadio kussu descienden todos de la misma raíz. Con todo, la palabra tiene un lado más humilde: Elí se sienta en su כִּסֵּא junto al dintel del tabernáculo (1 S 1:9), recordándonos que todo trono es, en el fondo, una silla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3680', 'spa', 'Cubrir, ocultar, vestir; ser cubierto; cubrirse a sí mismo; abrumar o envolver', 'El verbo hebreo primario para colocar algo sobre una superficie de modo que la oculte, proteja o encierre. En el Piel describe cubrir la tierra con agua (Gn 7:19), cubrir sangre con polvo (Lv 17:13) o una nube cubriendo el tabernáculo (Nm 9:15). Desde la cobertura física, el verbo se extiende naturalmente a encubrir pecado u ocultar faltas: Proverbios traza el contraste entre el necio que ''cubre la vergüenza'' y el prudente que ''encubre el conocimiento'' (12:16, 23). El árabe preserva esta misma bifurcación: غطّى y ستر para la cobertura física frente a كتم y أخفى para ocultar secretos. El Hitpael reflexivo retrata figuras que se cubren con velo en señal de duelo o disfraz: Tamar cubriéndose ante Judá (Gn 38:14) o reyes que rasgan vestiduras y se cubren de cilicio ante Dios (2 R 19:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3682', 'spa', 'Cubierta o vestidura; ropa para el cuerpo, o figuradamente un regalo de encubrimiento o vindicación.', 'Este sustantivo femenino designa una cubierta, ya sea una prenda literal que se lleva sobre el cuerpo o un encubrimiento figurado. En el código de la alianza (Éx 21:10; 22:26), se refiere al derecho básico a la vestimenta que no debe negarse a los vulnerables. Job emplea esta palabra para describir a los indigentes que carecen de abrigo contra el frío (Job 24:7; 31:19). De manera más llamativa, en Génesis 20:16, el regalo de plata de Abimelec se denomina «cubierta de los ojos», una expresión diplomática que significa vindicación o compensación para que el honor de Sara quede públicamente restaurado. Isaías 50:3 extiende la imagen a escala cósmica: Dios viste los cielos con cilicio como su cubierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3684', 'spa', 'kesil — un necio, un insensato; aquel que es moralmente obtuso y rechaza obstinadamente la sabiduría', 'kesil — un necio, un insensato; aquel que es moralmente obtuso y rechaza obstinadamente la sabiduría');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3685', 'spa', 'Orión (constelación); el gran cazador atado en los cielos, asociado con las Pléyades', 'כְּסִיל designa la brillante constelación de Orión, mencionada frecuentemente junto a las Pléyades en la astronomía bíblica. El nombre emplea irónicamente la palabra hebrea para «necio», aunque la conexión con el nombre de la constelación es oscura; quizás se relaciona con mitos sobre un gigante presuntuoso atado en los cielos. Job pregunta si alguien puede «desatar las ligaduras de Orión», aludiendo a mitos del antiguo Cercano Oriente sobre el poderoso cazador fijado como constelación. Isaías habla de varios «Oriones», refiriéndose a Orión y otras constelaciones brillantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3689', 'spa', 'Lomos o ijares (anatómico); confianza o seguridad; necedad o insensatez — tres dominios semánticos distintos.', 'Lomos o ijares (anatómico); confianza o seguridad; necedad o insensatez — tres dominios semánticos distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3691', 'spa', 'Kislev, noveno mes del calendario judío (noviembre-diciembre)', 'Nombre de mes de origen babilónico adoptado durante el exilio, correspondiente al final del otoño. Kislev abarca desde mediados de noviembre hasta mediados de diciembre en el calendario moderno. Nehemías recibió en este mes el inquietante informe sobre las murallas de Jerusalén en ruinas, y Zacarías fechó una de sus visiones nocturnas en Kislev. El nombre refleja la adopción generalizada de la terminología calendárica babilónica en el judaísmo postexílico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3698', 'spa', 'Espelta, cereal resistente similar al trigo (Triticum spelta)', 'Variedad de cereal antiguo, más resistente y tolerante a la sequía que el trigo común, cultivado en Egipto e Israel. La espelta madura más tarde que la cebada y el trigo, lo cual explica por qué sobrevivió a la séptima plaga de granizo en Éxodo mientras los cultivos más tempranos fueron destruidos. Isaías la menciona entre los granos sembrados en hileras ordenadas, ilustrando la sabiduría del agricultor en el manejo de sus cultivos, como metáfora del gobierno providencial de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3700', 'spa', 'Anhelar profundamente, desear con intensidad; expresa un anhelo ferviente o nostalgia, a menudo dirigido hacia Dios o el hogar.', 'Verbo de anhelo emocional intenso, empleado tanto en las conjugaciones Qal como Nifal sin diferencia clara de significado entre ambas. Su aparición más memorable es la construcción de infinitivo absoluto Nifal en Génesis 31:30, donde Labán acusa a Jacob: «anhelabas grandemente la casa de tu padre». Los Salmos lo emplean para expresar deseo espiritual: el alma que «anhela, y aun desfallece» por los atrios de Dios (Sal 84:2). Tanto el alemán Sehnsucht como el español anhelar captan el dolor del deseo que transmite esta palabra. El cognado árabe kasafa («eclipsarse, oscurecerse») sugiere una asociación original con la palidez, la apariencia física de alguien consumido por la añoranza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3701', 'spa', 'Plata como metal precioso; por extensión, dinero o moneda pesada para pago, compra o redención.', 'Una de las palabras de mayor peso económico en la Biblia hebrea, כֶּסֶף designa tanto el metal físico —la plata— como el dinero derivado de él. En el antiguo Oriente Próximo, la plata funcionaba como principal medio de cambio mucho antes de la moneda acuñada, de modo que el mismo vocablo abarca desde los relucientes utensilios del templo hasta el pago que Abraham contó para la cueva de Macpela (Gn 23:15-16). El español plata reproduce esta misma polisemia casi exactamente: metal y dinero en una sola voz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3702', 'spa', 'Plata, dinero — el metal precioso usado como material y moneda (arameo). Sustantivo arameo para la plata, que aparece exclusivamente en Daniel y Esdra', 'Plata, dinero — el metal precioso usado como material y moneda (arameo). Sustantivo arameo para la plata, que aparece exclusivamente en Daniel y Esdras. Funciona en dos sentidos estrechamente relacionados: como material físico en la estatua de Nabucodonosor y los vasos del templo (Dan 2:32, 35, 45; 5:2, 4, 23; Esd 5:14; 6:5), y como moneda o valor monetario en decretos reales que financiaban la reconstrucción del templo (Esd 7:15–18, 22). El español ''plata'' y el francés ''argent'' conservan este doble alcance de metal y dinero, reflejando exactamente su cognado hebreo כֶּסֶף. La palabra refleja el mundo económico postexílico donde la plata era el patrón de intercambio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3705', 'spa', 'Ahora — adverbio temporal arameo que marca el tiempo presente o una transición lógica. Adverbio arameo que significa ''ahora'', usado para anclar el dis', 'Ahora — adverbio temporal arameo que marca el tiempo presente o una transición lógica. Adverbio arameo que significa ''ahora'', usado para anclar el discurso en el momento presente o para introducir el siguiente paso lógico en un argumento. Aparece a lo largo de Daniel y Esdras en decretos reales, oraciones y correspondencia oficial. En Esdras típicamente abre una nueva sección de directiva administrativa — ''ahora pues'' (Esd 4:13–14, 21; 5:17; 6:6) — mientras que en Daniel marca transiciones en la narrativa y la oración (Dan 2:23; 3:15; 4:37; 5:12, 15–16; 6:8). La frase עַד־כְּעַן ''hasta ahora'' en Esdras 5:16 extiende su uso para marcar duración. El español ''ahora'', el francés ''maintenant'' y el alemán ''jetzt/nun'' confirman el significado temporal directo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3706', 'spa', 'y ahora (arameo); fórmula epistolar que introduce el asunto principal de cartas oficiales', 'Esta frase adverbial aramea, contracción de una forma más extensa, funciona como fórmula epistolar en la correspondencia oficial. Introduce el asunto sustantivo de una carta después del saludo, equivalente a «y ahora, respecto al asunto en cuestión». Todas sus apariciones bíblicas se encuentran en cartas preservadas en las secciones arameas de Esdras, donde funcionarios persas escriben a y desde la comunidad judía. Antiguamente se malinterpretaba como «etcétera», pero los papiros arameos de Egipto confirmaron su significado como «y ahora», marcando la transición de la apertura al cuerpo de la carta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3707', 'spa', 'Provocar a ira o estar airado; en forma causativa, incitar la cólera (especialmente divina), o intransitivamente experimentar enojo o indignación uno ', 'Provocar a ira o estar airado; en forma causativa, incitar la cólera (especialmente divina), o intransitivamente experimentar enojo o indignación uno mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3708a', 'spa', 'Vejación, pesar o provocación; la angustia interior del agraviado o la ira suscitada por la idolatría.', 'Vejación, pesar o provocación; la angustia interior del agraviado o la ira suscitada por la idolatría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3708b', 'spa', 'vejación, aflicción, ira (variante dialectal de כַּעַס, exclusiva de Job)', 'Este sustantivo, variante dialectal del más común כַּעַס, aparece exclusivamente en la poesía de Job para describir angustia emocional, ya sea la vejación y aflicción humana o la ira divina. El término capta la irritación, frustración e indignación que produce el sufrimiento, como cuando Job suplica a Dios que comprenda su «aflicción» y angustia. Puede describir tanto el dolor interior del afligido como la ira manifiesta de Dios contra el pecado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3709', 'spa', 'Palma de la mano, planta del pie; también: cucharilla/recipiente cultual, cavidad de la cadera, pata, manija, rama de palmera.', 'El sustantivo כַּף abarca todo lo cóncavo, ahuecado o plano, partiendo de la palma abierta de la mano. Desde la palma que Moisés extiende en oración (Éx 9:29) hasta la planta del pie que no halla reposo (Gn 8:9), כַּף cartografía las concavidades naturales del cuerpo. Se extiende por metáfora a los utensilios cúlticos con forma de palma abierta (las cucharillas del tabernáculo, Nm 7:84), a la cavidad de la articulación de Jacob (Gn 32:25) e incluso a las manijas de un cerrojo (Cnt 5:5). Su genio reside en una lógica basada en la forma: donde hay una superficie hueca o plana, כַּף puede aplicarse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3712', 'spa', 'Fronda o rama de palmera, usada figuradamente para representar nobleza y alto estatus social', 'La copa frondosa o rama de la palmera, empleada como metáfora social. Isaías contrasta dos veces la ''rama de palmera'' (que representa a nobles y dirigentes) con el ''junco'' (que representa al pueblo llano), usando la jerarquía botánica para ilustrar la totalidad del juicio, desde los más encumbrados hasta los más humildes. Job aplica la imagen al impío cuya fronda no reverdecerá, evocando un marchitamiento prematuro a pesar de una promesa inicial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3713a', 'spa', 'Tazón o recipiente de oro o plata usado como vaso sagrado en el servicio del templo.', 'Este sustantivo designa un tazón o recipiente elaborado en metal precioso para uso en el templo. Las nueve apariciones se concentran en textos tardíos que describen el ajuar sagrado: las especificaciones de David para tazones de oro y plata en 1 Crónicas 28:17, y el inventario de utensilios devueltos del exilio babilónico en Esdras 1:10 y 8:27. La palabra está emparentada con el arameo kephora, lo que sugiere un recipiente ancho y abierto. Aunque el español lo traduce como «tazas» o «copas», el hebreo evoca específicamente el contexto ritual del culto en el templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3713b', 'spa', 'Escarcha, hielo blanco formado por la congelación del rocío', 'Los delicados cristales de hielo blanco que se forman en las mañanas frías cuando el rocío se congela. Éxodo compara la apariencia del maná con la escarcha sobre el suelo: fina, blanca, escamosa. El salmista celebra a Dios esparciendo la escarcha como ceniza, parte de los fenómenos invernales bajo control divino. En el interrogatorio divino de Job, el origen de la escarcha se cuenta entre los misterios de la creación que superan el dominio humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3715a', 'spa', 'León joven — un león adolescente con edad suficiente para cazar, usado literal y figuradamente como imagen de poder feroz', 'León joven — un león adolescente con edad suficiente para cazar, usado literal y figuradamente como imagen de poder feroz');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3716', 'spa', 'Quefirá, ciudad hevea/gabaonita asignada después a Benjamín, la moderna Kefireh', 'Quefirá fue una de las cuatro ciudades gabaonitas que hicieron un pacto con Josué mediante engaño, pretendiendo venir de una tierra lejana cuando en realidad vivían cerca. Tras la conquista, fue asignada al territorio tribal de Benjamín. La ciudad aparece en los censos postexílicos, lo que demuestra que los que retornaron del exilio la repoblaron. Los eruditos modernos la identifican con Kefireh, situada en la región montañosa al oeste de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3717', 'spa', 'Doblar, plegar; en pasivo: doblado, plegado en dos; nifal: ser doblado (de una espada).', 'כָּפַל describe la accion de doblar o plegar algo sobre si mismo, un termino concreto tomado del trabajo textil y artesanal. En Exodo 26:9 se refiere a doblar la sexta cortina del tabernaculo, mientras que en Exodo 28:16 y 39:9 describe el pectoral del sumo sacerdote hecho como un cuadrado plegado en dos. El uso mas dramatico aparece en Ezequiel 21:14, donde la espada del profeta recibe la orden de ''ser doblada'', una intensificacion del juicio divino. Cognados en arameo, siriaco y arabe confirman el significado central de doblar o plegar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3718', 'spa', 'Doble, el duplo de una cantidad o medida', 'Término que denota dualidad o duplicación, usado con mayor frecuencia en la forma dual כִּפְלַיִם. Isaías promete que Jerusalén recibirá doble consolación por su sufrimiento. Los amigos de Job señalan que la verdadera sabiduría es ''doble'' respecto al entendimiento humano: los caminos de Dios exceden nuestras categorías por un factor de dos. La palabra también describe las formidables mandíbulas dobles de Leviatán en Job 41.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3721', 'spa', 'Encorvar, inclinar, estar encorvado; del afligido o humilde que se inclina ante Dios.', 'כָּפַף transmite el acto fisico y espiritual de encorvarse o inclinarse, ya sea bajo el peso de la afliccion o en adoracion deliberada. En el Salmo 57:6 el alma del salmista esta ''encorvada'' bajo la persecucion, mientras que Isaias 58:5 cuestiona si meramente inclinar la cabeza como un junco constituye un verdadero ayuno. El participio pasivo ''los encorvados'' (כְּפוּפִים) en los Salmos 145:14 y 146:8 se convierte en una tierna designacion de los afligidos a quienes el Senor levanta. Miqueas 6:6 emplea el nifal reflexivo para inclinarse ante Dios en adoracion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3722a', 'spa', 'Hacer expiación, cubrir el pecado; apaciguar, pacificar; perdonar — el verbo central del sistema sacrificial de Israel.', 'El verbo definitorio de la teología expiatoria de Israel, que aparece abrumadoramente en contextos rituales levíticos. Construido sobre la imagen concreta de cubrir o recubrir, el tronco Piel se desarrolló como término técnico para la expiación cúltica: el acto sacerdotal de hacer expiación mediante el sacrificio de sangre para restaurar la posición del adorador ante Dios. Más allá del altar, la palabra se extiende a apaciguar la ira humana (Gn 32:20), al perdón divino sin sacrificio (Sal 78:38) y a la esperanza teológica de que el pecado sea cubierto y eliminado (Dn 9:24). Su arco semántico, del recubrimiento físico a la reconciliación espiritual, traza la trayectoria de la soteriología bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3724a', 'spa', 'Precio de rescate pagado para redimir una vida o evitar un castigo; también soborno dado para pervertir la justicia. Sustantivo que significa el preci', 'Precio de rescate pagado para redimir una vida o evitar un castigo; también soborno dado para pervertir la justicia. Sustantivo que significa el precio pagado por una vida, enraizado en el verbo kapar (''cubrir, expiar''). En su sentido principal denota un rescate o pago de redención legítimo: la compensación por una muerte causada por un buey (Éx 21:30), el impuesto de medio siclo del censo ''como rescate por su vida'' (Éx 30:12), y la prohibición de aceptar rescate por un homicida (Núm 35:31-32). El salmista declara que nadie puede pagar a Dios rescate suficiente por su propia alma (Sal 49:8), e Isaías presenta a Dios entregando Egipto ''como tu rescate'' por Israel (Is 43:3). En dos pasajes proféticos, sin embargo, la palabra adquiere el matiz más oscuro de soborno que corrompe la justicia, un significado que la evidencia multilingüe marca claramente: el inglés y el alemán cambian a ''bribe'' mientras que el español usa ''soborno'' en lugar de ''rescate''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3725', 'spa', 'kippurim -- expiación/expiaciones; sustantivo abstracto para la expiación ritual, usado solo en legislación sacerdotal', 'El sustantivo abstracto plural כִּפֻּרִים (''expiaciones'') es la forma nominal detrás del día más solemne del calendario israelita: יוֹם הַכִּפֻּרִים, el Día de la Expiación (Lev 23:27-28; 25:9). Con solo siete apariciones, todas dentro de legislación sacerdotal, designa el proceso ritual mediante el cual la culpa es cubierta y la relación entre Dios y su pueblo es restaurada. Califica la ofrenda por el pecado (חַטַּאת הַכִּפֻּרִים, Éx 30:10; Núm 29:11), el carnero de consagración (אֵיל הַכִּפֻּרִים, Núm 5:8) y el dinero de rescate (כֶּסֶף הַכִּפֻּרִים, Éx 30:16). La idea raíz es la de cubrir o limpiar la ofensa para restaurar la comunión con Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3727', 'spa', 'Propiciatorio: la plancha de oro macizo sobre el Arca del Pacto donde la presencia de Dios moraba entre los querubines.', 'Propiciatorio: la plancha de oro macizo sobre el Arca del Pacto donde la presencia de Dios moraba entre los querubines.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3729', 'spa', 'atar, amarrar (arameo); ser atado con cuerdas o grillos', 'Este verbo arameo describe la acción de atar o amarrar a alguien, particularmente con cuerdas o grillos. Aparece exclusivamente en el relato de Daniel sobre los tres hebreos arrojados al horno de Nabucodonosor, donde el énfasis en que fueron «atados» resalta la naturaleza milagrosa de su preservación: salieron desatados e ilesos mientras sus verdugos perecieron. Los cognados arameos en siríaco y otras lenguas semíticas afines describen igualmente las acciones de anudar, retorcer y ligar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3730', 'spa', 'Cáliz o botón ornamental del candelabro de oro (menorá); también el capitel o remate superior de una columna', 'Cáliz o botón ornamental del candelabro de oro (menorá); también el capitel o remate superior de una columna');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3731', 'spa', 'Caftor, probablemente Creta, lugar de origen de los filisteos', 'Designación geográfica de la región de donde procedían los filisteos, ampliamente identificada con Creta según evidencias lingüísticas e históricas. Amós recuerda a Israel que, así como Dios los sacó de Egipto, también trajo a los filisteos desde Caftor, ambas migraciones bajo la soberanía divina. El nombre se vincula con el pueblo caftoreo y posiblemente con los Keftiu mencionados en textos egipcios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3732', 'spa', 'Caftoreos, pueblo originario de Caftor, antepasados de los filisteos', 'Gentilicio para los habitantes de Caftor, incluidos en la Tabla de las Naciones como descendientes de Mizraim (Egipto). Las evidencias históricas y arqueológicas sugieren que eran pueblos egeos, posiblemente de Creta, que migraron a la costa meridional del Levante y se convirtieron en los filisteos. Su desplazamiento de los aveos estableció la pentápolis filistea que más tarde se enfrentaría a Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3733b', 'spa', 'Pasto, pradera donde apacientan los rebaños', 'Tierra de pastoreo cubierta de hierba donde pacen los rebaños, distinta de los campos cultivados. El salmista emplea imágenes pastoriles de praderas «vestidas de ovejas» para celebrar la provisión del Creador y la fertilidad de la tierra. Isaías promete «un pasto espacioso» como parte de la bendición futura, con amplio lugar para que los rebaños pazcan en seguridad. El término puede estar emparentado con כַּר (carnero/cordero), lo que sugiere un campo propio para el apacentamiento de corderos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3733c', 'spa', 'Cordero o carnero joven (animal); ariete (arma de asedio)', 'El sustantivo כַּר porta dos significados notablemente distintos unidos por la imagen del carnero. En su sentido primario designa un cordero o macho joven de oveja, apreciado por su grasa (Dt 32:14) y ofrecido como tributo (Isa 16:1, 2 R 3:4). Amós retrata el lujo de la elite samaritana festejando con corderos del rebaño (Am 6:4), y los mercaderes de Ezequiel comercian con ellos (Ez 27:21). El sentido secundario es el ariete — la máquina de asedio que recibe su nombre, al igual que en latín, del animal que embiste — y aparece solo en las vívidas profecías de asedio de Ezequiel (Ez 4:2; 21:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3734a', 'spa', 'Cor; una unidad grande de medida seca (y ocasionalmente líquida), equivalente a unos 220 litros o 6 fanegas.', 'Sustantivo que designa el cor (también escrito kor), una de las mayores unidades de medida estándar del antiguo Israel, equivalente al homer y a aproximadamente 220 litros o 6 fanegas. Las provisiones diarias de Salomón incluían treinta cors de flor de harina y sesenta cors de harina común (1 R 4:22), mientras que Ezequiel 45:14 define el cor como medida líquida para el aceite. La palabra pasó al griego como koros y al árabe como kurr, testimonio de su uso extendido en el comercio del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3738b', 'spa', 'Cavar, excavar, negociar o perforar; principalmente cavar pozos, fosas y tumbas, con extensiones al comercio y a la apertura figurada', 'Cavar, excavar, negociar o perforar; principalmente cavar pozos, fosas y tumbas, con extensiones al comercio y a la apertura figurada');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3742', 'spa', 'Querubín; ser sobrenatural alado que custodia el espacio sagrado y porta la presencia divina.', 'Querubín; ser sobrenatural alado que custodia el espacio sagrado y porta la presencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3746', 'spa', 'Caritas, unidad de guardaespaldas extranjeros al servicio de los reyes de Judá', 'Una unidad militar de élite, posiblemente mercenarios carios procedentes de Asia Menor, que servían como guardaespaldas reales junto a los cereteos. Durante el golpe de Joiada contra Atalía, el sacerdote introdujo a estos guardias en los recintos del templo para proteger al joven rey Joás. Su presencia refleja la práctica del antiguo Cercano Oriente de emplear soldados profesionales extranjeros para la seguridad del palacio, garantizando una lealtad libre de compromisos políticos locales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3748', 'spa', 'divorcio, el acto legal de repudio; siempre en la frase ''carta de divorcio''', 'Este sustantivo aparece exclusivamente en la expresión ''carta de divorcio'' (sefer keritut), que designa el documento legal mediante el cual un hombre repudia formalmente a su esposa bajo la ley mosaica. Deuteronomio exige dicho certificado escrito para formalizar el divorcio, protegiendo los derechos y el estatus legal de la mujer. Los profetas emplean la metáfora de la carta de divorcio para describir la relación de Dios con Israel infiel: Isaías pregunta dónde está la carta, insinuando que Dios no ha repudiado realmente a Israel, mientras que Jeremías declara que Dios entregó la carta de divorcio a Israel apóstata por causa de su adulterio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3751', 'spa', 'Carquemis, importante ciudad hitita a orillas del Éufrates', 'Una destacada ciudad antigua en la ribera occidental del Éufrates, que sirvió como capital de un reino hitita y luego como centro asirio y neobabilónico. Su mención en Isaías representa el avance implacable de la conquista asiria. El faraón Necao II marchó hacia Carquemis en el 609 a. C., y el rey Josías lo interceptó fatalmente en Megido. Más tarde, en el 605 a. C., la victoria decisiva de Nabucodonosor sobre Egipto en Carquemis trasladó el poder del Cercano Oriente a Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3754', 'spa', 'Viña; terreno cultivado donde se plantan y cuidan vides.', 'Viña; terreno cultivado donde se plantan y cuidan vides.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3755', 'spa', 'Vinador, el que cuida y cultiva vinedos.', 'כֹּרְמִים (''vinadore'') designa a quienes cuidan y cultivan las vides, una ocupacion vital en la economia agraria del antiguo Israel. El termino aparece exclusivamente como participio plural, siempre emparejado con ''labradores'' (אִכָּרִים) o ''agricultores'' (יֹגְבִים), reflejando los dos pilares de la agricultura israelita. En 2 Reyes 25:12 y Jeremias 52:16, Nabucodonosor deja atras a vinadore y labradores como los mas pobres de la tierra tras el exilio, un detalle conmovedor que muestra que incluso en la catastrofe la vina debe ser atendida. Isaias 61:5 vislumbra a extranjeros sirviendo como vinadore de Israel en la restauracion mesianica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3756', 'spa', 'Carmi; nombre propio de un hijo de Rubén y del padre de Acán, el que turbó a Israel.', 'Nombre propio que identifica al menos a dos individuos en la Biblia hebrea. El primero es Carmi hijo de Rubén, incluido entre quienes descendieron a Egipto (Gn 46:9; Éx 6:14; Nm 26:6; 1 Cr 5:3), antepasado del clan carmita. El segundo es Carmi hijo de Zabdi, de la tribu de Judá, padre de Acán, quien violó el anatema en Jericó (Jos 7:1, 18; 1 Cr 2:7). El nombre posiblemente deriva de kerem («viña»), lo que sugiere el significado «mi viña» o «viñador». La tradición griega lo transcribe como Charmei.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3758', 'spa', 'Carmesí, tinte rojo intenso o tela teñida de carmesí', 'Un tinte rojo intenso o púrpura-rojizo, y la tela teñida con él, probablemente derivado del insecto quermes. Crónicas incluye el carmesí entre los materiales preciosos importados para la construcción del templo, agrupado con el azul, la púrpura y el lino fino. Este préstamo del persa sugiere que era una importación de lujo, quizá de regiones especializadas en tintes rojos de alta calidad. El término se distingue del más común «escarlata» (שָׁנִי).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3759', 'spa', 'Campo fértil, tierra cultivada, terreno productivo; también grano fresco o espigas sin madurar', 'Campo fértil, tierra cultivada, terreno productivo; también grano fresco o espigas sin madurar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3760', 'spa', 'Carmelo: (1) el célebre promontorio montañoso en la costa mediterránea; (2) una ciudad en Judá; (3) como sustantivo común, tierra fértil o campo fruct', 'Carmelo: (1) el célebre promontorio montañoso en la costa mediterránea; (2) una ciudad en Judá; (3) como sustantivo común, tierra fértil o campo fructífero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3761', 'spa', 'Carmelita; adjetivo gentilicio que identifica a alguien oriundo de Carmel, aplicado a Nabal y al guerrero Hezrai.', 'Adjetivo gentilicio que significa ''el carmelita'', usado con articulo para designar a una persona oriunda de la ciudad de Carmel en la serrania de Juda (distinta del monte Carmelo en el norte). Identifica a Nabal como ''el carmelita'' en los relatos del periodo de David en el desierto (1 Sam 30:5; 2 Sam 2:2; 3:3), y al guerrero Hezrai en las listas de los valientes de David (2 Sam 23:35 = 1 Cr 11:37). La forma femenina aparece para Abigail en 1 Cr 3:1. El espanol ''el carmelita'' conserva la fuerza adjetival gentilicia, indicando origen geografico y no caracter personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3764', 'spa', 'Trono (arameo), asiento de autoridad real o divina', 'Palabra aramea para «trono» que aparece exclusivamente en las secciones arameas de Daniel. La visión apocalíptica de Daniel 7 presenta tronos divinos en plural — «fueron puestos tronos» — para el Anciano de Días, cuyo trono arde en fuego con ruedas de llamas. Daniel 5 relata cómo Nabucodonosor perdió su trono a causa de la soberbia y lo recuperó al reconocer la soberanía del cielo. El término subraya tanto la fragilidad de la realeza humana como el dominio eterno de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3766', 'spa', 'Inclinarse, arrodillarse, agacharse; abarca desde la adoración y sumisión hasta el colapso físico y la postura animal', 'Inclinarse, arrodillarse, agacharse; abarca desde la adoración y sumisión hasta el colapso físico y la postura animal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3767', 'spa', 'La parte inferior de la pata o pierna de un animal, usada en la ley ritual para la preparación sacrificial y normas alimentarias.', 'Este sustantivo se refiere a la parte inferior articulada de la pata de un animal, y aparece exclusivamente en contextos sacerdotales y rituales. En Éxodo 12:9, el cordero pascual debe asarse entero — «su cabeza con sus patas» — preservando la integridad del animal. Las instrucciones levíticas para el holocausto (Lv 1:9, 13; 8:21; 9:14) emparejan las patas con las entrañas como partes que deben lavarse antes de quemarse. Amós 3:12 emplea la imagen de forma vívida: un pastor rescata solo dos patas de la boca del león, metáfora de la destrucción casi total de Israel. Levítico 11:21 aplica esta palabra a las patas traseras articuladas de las langostas aptas para comer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3772', 'spa', 'Cortar — físicamente árboles u objetos, cortar un pacto, o ser cortado como castigo divino; abarca Qal, Nifal, Hifil y Hofal.', 'Un verbo cuya acción física concreta —cortar con una hoja— genera el modismo pactal más importante de la Biblia hebrea y su fórmula de juicio más severa. Cuando Abraham ''corta'' un pacto en Gn 15:18, la palabra preserva la memoria de un antiguo ritual en el que los animales se partían literalmente y las partes contratantes caminaban entre los pedazos. Cuando Dios amenaza con que un alma ''será cortada de su pueblo'' (Éx 12:15), la misma raíz porta una finalidad letal. La evidencia multilingüe rastrea estas divergencias con precisión: el hindi usa bandha (atar) para cortar un pacto, pero kaata (cortar) para la tala física, mostrando que los traductores reconocen marcos conceptuales radicalmente distintos pese a compartir la misma raíz hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3773', 'spa', 'Vigas labradas, hileras de madera de cedro usadas en la construcción del templo y palacio de Salomón', 'Vigas de madera labrada, específicamente las hileras de cedro colocadas como parte de la construcción del templo y el palacio de Salomón. La técnica arquitectónica consistía en alternar capas de piedra y madera: tres hileras de piedra tallada coronadas por una hilera de vigas de cedro, proporcionando tanto soporte estructural como coherencia estética. Este método constructivo era característico de la edificación monumental israelita con influencia fenicia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3774', 'spa', 'Quereteo(s) — gentilicio de un grupo etnico vinculado a los filisteos, posiblemente de origen cretense', 'Los quereteos (tambien escritos cereteos) eran un grupo etnico estrechamente asociado con los filisteos, probablemente originario de Creta, conexion que la Septuaginta hace explicita al traducir el nombre como Krētas en Ezequiel 25:16 y Sofonias 2:5. En la narrativa de David aparecen como la guardia personal de elite del rey junto a los peleteos, un cuerpo leal de mercenarios que siguio a David durante la revuelta de Absalon (2 Sam 15:18) y la coronacion de Salomon (1 Re 1:38, 44). Su territorio en el Neguev se menciona cuando David persigue a los amalecitas (1 Sam 30:14). La expresion ''quereteos y peleteos'' se convirtio practicamente en una formula fija para designar a la guardia real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3775', 'spa', 'Cordero, oveja joven — un pequeño ovino usado para sacrificio, alimento y riqueza pastoral. Sustantivo para cordero u oveja joven, variante metatética', 'Cordero, oveja joven — un pequeño ovino usado para sacrificio, alimento y riqueza pastoral. Sustantivo para cordero u oveja joven, variante metatética del más común כֶּבֶשׂ (kebes, H3532), con las consonantes transpuestas. Aparece en dos contextos principales: la economía pastoral de los rebaños de Jacob, donde los corderos se clasifican por color y marcas (Gén 30:32–33, 35, 40), y el sistema sacrificial levítico, donde los corderos sirven como holocaustos, ofrendas de paz y ofrendas por el pecado (Lev 1:10; 3:7; 4:35; 22:19, 27; Núm 18:17). Deuteronomio 14:4 lo incluye entre los animales limpios permitidos. El español ''cordero'', el francés ''agneau'' y el alemán ''Lamm/Schaf'' confirman uniformemente el significado de oveja joven.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3778', 'spa', 'Caldeos, Caldea — el pueblo del sur de Mesopotamia (especialmente bajo Nabucodonosor) y su territorio patrio.', 'Caldeos, Caldea — el pueblo del sur de Mesopotamia (especialmente bajo Nabucodonosor) y su territorio patrio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3779', 'spa', 'Caldeos — el pueblo babilónico y su casta erudita-sacerdotal de sabios. Sustantivo gentilicio arameo para los caldeos, que aparece en Daniel y Esdras ', 'Caldeos — el pueblo babilónico y su casta erudita-sacerdotal de sabios. Sustantivo gentilicio arameo para los caldeos, que aparece en Daniel y Esdras con dos referentes superpuestos. En su sentido étnico designa a la nación caldea y sus gobernantes — Belsasar como ''rey de los caldeos'' (Dan 5:30) y la destrucción caldea del templo (Esd 5:12). En su sentido especializado dentro de las narrativas cortesanas de Daniel, denota una clase erudita entre los magos babilónicos, convocada junto con magos y astrólogos para interpretar sueños y señales (Dan 2:5, 10; 4:4; 5:7, 11). El español ''caldeos'' y el alemán ''Chaldaeer'' preservan ambas dimensiones de esta designación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3782', 'spa', 'Tropezar, tambalear, vacilar; en Nifal, tropezar y caer; en Hifil, hacer tropezar; también debilitarse o fallar en fuerza.', 'Tropezar, tambalear, vacilar; en Nifal, tropezar y caer; en Hifil, hacer tropezar; también debilitarse o fallar en fuerza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3784', 'spa', 'Practicar la hechicería o brujería; verbo denominativo Piel para artes mágicas ilícitas, siempre condenadas.', 'Verbo denominativo Piel que designa la práctica de la hechicería, presentada siempre de forma negativa en las Escrituras. El participio femenino mekhashshephah («hechicera») aparece en la célebre prohibición de Éxodo 22:18, mientras que el masculino plural designa a los magos de las cortes extranjeras en Egipto (Éx 7:11) y Babilonia (Dn 2:2). La práctica de hechicería por parte de Manasés se enumera entre su catálogo de abominaciones (2 Cr 33:6). El español hechicero/hechicera traduce este término de manera consistente. El cognado acadio kasapu confirma que esta era una categoría reconocida de práctica mágica en todo el antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3785', 'spa', 'Hechicería, brujería; artes mágicas ilícitas, frecuentemente emparejadas con la inmoralidad sexual como metáfora de corrupción espiritual.', 'Forma sustantiva de כָּשַׁף, que aparece siempre en plural keshaphim («hechicerías»), designando la práctica de la magia ilícita. Lo distintivo de esta palabra es su frecuente emparejamiento con zenunim («prostituciones»): las hechicerías y prostituciones de Jezabel provocan la revuelta de Jehú (2 R 9:22), y Nínive es personificada como una ramera y «maestra de hechicerías» (Nah 3:4). Esta asociación sugiere que la hechicería se entendía no solo como una técnica, sino como un poder seductor y corruptor. Miqueas 5:12 promete que Dios «arrancará las hechicerías de tu mano», tratándolas casi como implementos físicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3787', 'spa', 'Prosperar, ser apropiado, resultar ventajoso (hebreo tardío)', 'Verbo que aparece en libros bíblicos tardíos (Ester, Eclesiastés) con el significado de ser apropiado, prosperar o resultar ventajoso. En Ester se emplea para expresar lo que es «recto ante los ojos del rey», usando el lenguaje del protocolo cortesano persa. Eclesiastés lo utiliza para expresar la incertidumbre sobre qué esfuerzos prosperarán y para señalar la ventaja que ofrece la sabiduría para alcanzar el éxito. Su sabor arameo refleja la evolución lingüística del período postexílico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3788', 'spa', 'Habilidad, éxito, provecho; capacidad para realizar algo o ventaja obtenida', 'Sustantivo del hebreo tardío que aparece exclusivamente en Eclesiastés, y designa tanto la habilidad aplicada al trabajo como el provecho o éxito resultante. Qohélet observa que todo trabajo hábil surge de la envidia competitiva, que una persona se esfuerza con sabiduría y habilidad solo para dejar el fruto a otro, y cuestiona qué provecho obtienen los dueños de sus posesiones. El término abarca tanto la capacidad humana como sus resultados, a menudo frustrantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3789', 'spa', 'Escribir, inscribir, registrar, componer; en pasivo: escrito, registrado; como sustantivo: escriba, escritor.', 'Un verbo fundamental de la civilización en el antiguo Oriente Próximo, כָּתַב cubre el acto completo de plasmar palabras en un soporte duradero: ya sea Moisés inscribiendo el pacto en tablas (Éx 24:4), un rey dictando cartas, o un escriba redactando un decreto legal. El participio pasivo Qal (כָּתוּב) se convirtió en la fórmula estándar para citar textos con autoridad: ''como está escrito.'' Cognado con el arameo כְּתַב, el fenicio ktb y tomado en préstamo por el árabe como كَتَبَ, refleja una cultura escribal semítica compartida. Los troncos Nifal y Piel extienden el rango desde el registro institucional hasta la identidad profesional del escriba.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3790', 'spa', 'Escribir, registrar por escrito; verbo arameo para componer cartas, decretos y visiones.', 'Verbo arameo que significa ''escribir'' o ''registrar por escrito'', presente en las conjugaciones Peal (activa) y Peʿil (pasiva) a lo largo de Esdras y Daniel. Sus ocho apariciones abarcan toda la gama de la actividad escribal antigua: componer cartas oficiales de acusación (Esd 4:8), registrar hallazgos legales en archivos (Esd 5:7; 6:2) y la escritura sobrenatural en la pared durante el banquete de Belsasar (Dn 5:5). El español capta el sentido activo con ''escribieron'' y ''escribió'', mientras que el pasivo ''fue escrito'' aparece en fórmulas oficiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3791', 'spa', 'Escritura: un documento escrito, carta o decreto; un sistema de escritura o alfabeto; un registro o archivo oficial', 'Escritura: un documento escrito, carta o decreto; un sistema de escritura o alfabeto; un registro o archivo oficial');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3792', 'spa', 'Escritura, documento escrito — inscripcion, decreto o texto; usado casi exclusivamente en las porciones arameas de Daniel y Esdras', 'El sustantivo כְּתָב (ketab) designa un escrito, una inscripcion o un documento oficial. Aparece casi exclusivamente en las secciones arameas de Daniel y Esdras, donde se refiere a decretos reales, a la misteriosa escritura en la pared y a las Escrituras sagradas. En Daniel 5:7-8, Belsasar promete recompensas a quien pueda leer la ''escritura'' en la pared del palacio. Daniel 10:21 habla de ''la escritura de verdad'', un libro celestial de decretos. En Esdras 6:18, los sacerdotes se organizan ''conforme a lo escrito en el libro de Moises''. El termino abarca desde lo inscrito hasta lo decretado oficialmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3794', 'spa', 'Quitim — originalmente los habitantes de Kition (Chipre), luego termino general para los pueblos del Mediterraneo occidental', 'Comenzando como referencia a los habitantes de Kition en Chipre (del toponimo fenicio kt/kty), este gentilicio se amplio a lo largo de los siglos para designar a los pueblos maritimos occidentales en general. En la Tabla de las Naciones, Quitim desciende de Javan/Grecia (Gn 10:4), anclando el termino en el mundo egeo. Isaias lo usa para Chipre especificamente (23:1, 12), mientras que las ''islas de Quitim'' de Jeremias (2:10) y la referencia de Ezequiel (27:6) lo extienden a las costas mediterraneas en sentido amplio. En tiempos de Daniel, ''naves de Quitim'' (11:30) designa la flota romana, un notable viaje semantico desde una sola ciudad chipriota hasta toda una civilizacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3795', 'spa', 'Machacado, majado; describe el aceite de oliva producido al machacar aceitunas en un mortero, la calidad mas fina para uso sagrado.', 'Adjetivo que significa ''machacado'' o ''majado'', usado exclusivamente en la frase fija שֶׁמֶן כָּתִית (''aceite machacado'') para describir el aceite de oliva de la mas alta calidad, producido no mediante prensa mecanica sino majando las aceitunas en un mortero. Este metodo laborioso daba un aceite mas puro y claro, reservado para el candelabro del tabernaculo (Ex 27:20; Lv 24:2) y para las ofrendas de cereal (Ex 29:40; Nm 28:5; 1 Re 5:11). Las aceitunas se machacaban hasta liberar su aceite mas fino, sin el sedimento del prensado mecanico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3800', 'spa', 'Oro fino, oro puro — término poético para el oro de la más alta calidad, a menudo asociado con Ofir o paz.', 'Sustantivo poético que designa oro de pureza y valor excepcionales, distinguido del zahav (oro) corriente por su rareza y registro literario. Aparece en la literatura sapiencial y la poesía profética, frecuentemente en estado constructo con topónimos como Ofir (Is 13:12; Job 28:16; Sal 45:9) o junto a paz, ''oro refinado'' (Cnt 5:11). Lamentaciones 4:1 se abre con la desgarradora pregunta ''¡Cómo se ha empañado el oro fino!'' — usando כֶּתֶם para simbolizar la gloria pasada de Sion, ahora deslustrada. El vocablo posiblemente sea un préstamo atestiguado en egipcio como kathama, lo que sugiere un antiguo término comercial internacional para el oro de primera calidad.');